registerClass12ExerciseBanks("pakstudy", {"1":{"lang":"ur","items":{"mcqs":[{"q":[["pak12-ch1-exercise-1",9]],"ob":1,"s":["سرسید احمد خان 1869ء میں اپنے بیٹے سید محمود کے ساتھ انگلستان گئے اور وہاں آکسفورڈ اور کیمبرج کے تعلیمی نظام کا مشاہدہ کیا۔"],"c":1},{"q":[["pak12-ch1-exercise-1",10]],"ob":1,"s":["1911ء میں تقسیمِ بنگال کی تنسیخ کے بعد مسلم لیگ نے 1913ء میں اپنے مقاصد میں ترمیم کی اور ہندوستان کے لیے موزوں نظامِ خود اختیاری (سیلف گورنمنٹ) کا حصول اپنا مقصد قرار دیا۔"],"c":2},{"q":[["pak12-ch1-exercise-1",11]],"ob":1,"s":["اکتوبر 1906ء میں سر آغا خان کی قیادت میں 35 مسلمان راہنماؤں کا وفد (شملہ وفد) وائسرائے لارڈ منٹو سے شملہ میں ملا۔"],"c":1},{"q":[["pak12-ch1-exercise-1",12]],"ob":1,"s":["1911ء میں برطانوی حکومت نے مسلمانوں کی مرضی کے خلاف تقسیمِ بنگال کی تنسیخ کا اعلان کیا۔ (میثاقِ لکھنؤ 1916ء، تقسیمِ بنگال 1905ء اور مسلم لیگ کا قیام 1906ء میں ہوا۔)"],"c":3},{"q":[["pak12-ch1-exercise-1",13]],"ob":1,"s":["3 جون 1947ء کو وائسرائے لارڈ ماؤنٹ بیٹن نے تقسیمِ ہند کے منصوبے کا اعلان کیا۔"],"c":1},{"q":[["pak12-ch1-exercise-1",14]],"ob":1,"s":["انڈین نیشنل کانگریس کی بنیاد 1885ء میں ایک ریٹائرڈ انگریز افسر اے۔ او۔ ہیوم نے رکھی۔"],"c":3}],"objective":[{"q":[["pak12-ch1-exercise-1",2]],"s":["غدر (Mutiny)","1857ء کی جنگِ آزادی کو انگریز مؤرخین نے \"غدر\" کا نام دیا، جبکہ برصغیر کے مؤرخین اسے جنگِ آزادی کہتے ہیں۔"],"a":"غدر (Mutiny)"},{"q":[["pak12-ch1-exercise-1",3]],"s":["سر سلیم اللہ خان (نواب آف ڈھاکہ)","دسمبر 1906ء میں ڈھاکہ میں محمڈن ایجوکیشنل کانفرنس کے اجلاس کے بعد سر سلیم اللہ خان نے مسلم لیگ کے قیام کی تجویز پیش کی۔"],"a":"سر سلیم اللہ خان (نواب آف ڈھاکہ)"},{"q":[["pak12-ch1-exercise-1",4]],"s":["خاندانِ غلاماں","1206ء میں شہاب الدین محمد غوری کی وفات کے بعد قطب الدین ایبک نے جس حکومت کی بنیاد رکھی اسے خاندانِ غلاماں کہا جاتا ہے۔"],"a":"خاندانِ غلاماں"},{"q":[["pak12-ch1-exercise-1",5]],"s":["لارڈ منٹو","اکتوبر 1906ء میں شملہ وفد نے وائسرائے لارڈ منٹو سے ملاقات کی۔"],"a":"لارڈ منٹو"},{"q":[["pak12-ch1-exercise-1",6]],"s":["یومِ نجات","کانگریسی وزارتوں کے مستعفی ہونے پر قائدِاعظم کی اپیل پر مسلمانوں نے 22 دسمبر 1939ء کو یومِ نجات منایا۔"],"a":"یومِ نجات"},{"q":[["pak12-ch1-exercise-1",7]],"s":["تین (3)","1946ء میں برطانوی کابینہ کے تین ارکان پر مشتمل وفد (کابینہ مشن) ہندوستان آیا۔"],"a":"تین (3)"},{"q":[["pak12-ch1-exercise-1",16]],"tf":"tf","s":["غلط۔ علی گڑھ کالج میں دیگر قومیتوں کے طلبہ بھی پڑھتے تھے مگر دینیات کی تعلیم صرف مسلمان طلبہ کے لیے لازمی تھی، سب کے لیے نہیں۔"],"c":1},{"q":[["pak12-ch1-exercise-1",17]],"tf":"tf","s":["غلط۔ محمڈن ایجوکیشنل کانفرنس 1886ء میں سرسید احمد خان نے قائم کی تھی، مولانا محمد علی جوہر نے نہیں۔"],"c":1},{"q":[["pak12-ch1-exercise-1",18]],"tf":"tf","s":["غلط۔ 1908ء میں مسلم لیگ کا دستور بنا تو سر سلطان محمد آغا خان (سوم) اس کے صدر مقرر ہوئے۔ قائدِاعظم 1913ء میں مسلم لیگ میں شامل ہوئے۔"],"c":1},{"q":[["pak12-ch1-exercise-1",19]],"tf":"tf","s":["غلط۔ 1914ء میں شروع ہونے والی پہلی عالمی جنگ میں ترکی (سلطنتِ عثمانیہ) نے برطانیہ اور اس کے اتحادیوں کے خلاف جرمنی کا ساتھ دیا۔"],"c":1},{"q":[["pak12-ch1-exercise-1",20]],"tf":"tf","s":["درست۔ ہندو اخبارات نے قراردادِ لاہور کو \"قراردادِ پاکستان\" کا نام دیا حالانکہ قرارداد کے متن میں کہیں بھی لفظ پاکستان استعمال نہیں ہوا تھا۔"],"c":0},{"q":[["pak12-ch1-exercise-1",21]],"tf":"tf","s":["درست۔ وائسرائے لارڈ ماؤنٹ بیٹن نے 3 جون 1947ء کو تقسیمِ ہند کا منصوبہ پیش کیا۔"],"c":0},{"q":[["pak12-ch1-exercise-1",28]],"d":"pak12-ch1-match","s":["درست جوڑ (کالم ج):","1877ء — علی گڑھ کالج کا قیام (محمڈن اینگلو اورینٹل کالج کا سنگِ بنیاد)۔","1905ء — تقسیمِ بنگال۔","1916ء — میثاقِ لکھنؤ۔","1942ء — کرپس مشن۔","1946ء — کابینہ مشن۔"]}],"shortQuestions":[{"q":[["pak12-ch1-exercise-1",23]],"s":["شمالی ہندوستان میں باقاعدہ مسلمان حکومت کی بنیاد 1192ء میں شہاب الدین محمد غوری نے رکھی۔","ان کی وفات (1206ء) کے بعد قطب الدین ایبک نے دہلی میں خاندانِ غلاماں کی حکومت قائم کی۔ (اس سے پہلے 712ء میں محمد بن قاسم نے سندھ فتح کیا تھا۔)"]},{"q":[["pak12-ch1-exercise-1",24]],"s":["سرسید احمد خان کے نزدیک مسلمانوں کی تمام مشکلات کا حل جدید مغربی علوم اور انگریزی زبان کا حصول اور انگریز حکمرانوں سے اچھے تعلقات قائم کرنا تھا۔","ان کا مشورہ تھا کہ مسلمان فی الحال سیاست سے دور رہ کر اپنی پوری توجہ تعلیمی ترقی پر مرکوز کریں۔"]},{"q":[["pak12-ch1-exercise-1",25]],"s":["ہندوستان میں دو بڑی قومیں ہندو اور مسلمان آباد تھیں جن میں ہندو اکثریت اور مسلمان اقلیت میں تھے۔","مغربی جمہوریت اکثریت کی حکومت ہے، اس لیے اگر یہ نظام بغیر رد و بدل کے نافذ ہوتا تو مسلمان اقلیت ہمیشہ کے لیے ہندو اکثریت کی غلام بن جاتی۔ اسی لیے متحدہ ہندوستان میں یہ نظام قابلِ عمل نہ تھا۔"]},{"q":[["pak12-ch1-exercise-1",26]],"s":["1۔ قانون ساز کونسلوں کے انتخابات میں مسلمانوں کو جداگانہ طرزِ انتخاب کا حق دیا جائے تاکہ وہ اپنے نمائندے خود منتخب کریں۔","2۔ قانون ساز اداروں میں مسلمانوں کی نمائندگی کا تناسب طے کرتے وقت ان کی تعداد کے ساتھ ان کی سیاسی اہمیت کو بھی مدِنظر رکھا جائے۔","3۔ مسلمانوں کو سرکاری ملازمتوں اور مقامی حکومتی اداروں میں ان کا جائز حصہ دیا جائے۔"]},{"q":[["pak12-ch1-exercise-1",27]],"s":["کانگریس نے کرپس تجاویز اس لیے مسترد کیں کہ ان میں فوری طور پر ذمہ دار حکومت کے قیام کا مطالبہ تسلیم نہیں کیا گیا تھا، اور صوبوں کو وفاق سے الگ رہنے کا حق دیا گیا تھا جس سے پاکستان کی راہ ہموار ہوتی۔","مسلم لیگ نے انہیں اس لیے مسترد کیا کہ ان میں قیامِ پاکستان کی واضح ضمانت نہیں دی گئی تھی۔"]}],"longQuestions":[{"q":[["pak12-ch1-exercise-2",0]],"s":["نظریہ سے مراد وہ بنیادی سوچ، عقائد اور اصول ہیں جن پر کوئی قوم متفق ہو اور جو اس کی زندگی کا مقصد اور سمت متعین کرتے ہیں۔","تاریخ، مذہبی عقائد، سماجی اقدار اور تہذیب و ثقافت نظریہ کے وجود میں آنے اور پروان چڑھنے میں بنیادی کردار ادا کرتے ہیں۔","وجود میں آنے کے بعد نظریہ خود اس قوم کے عقائد، اقدار، تہذیب اور ثقافت کا بہترین محافظ ثابت ہوتا ہے؛ نظریہ جتنا مضبوط ہو قوم اتنی ہی متحد اور مضبوط ہوتی ہے۔","نظریہ قوم میں اتحاد، نظم و ضبط اور قربانی کا جذبہ پیدا کرتا ہے، قومی پالیسیوں اور قوانین کی بنیاد فراہم کرتا ہے اور مشکل وقت میں راہنمائی کرتا ہے۔","مثال: نظریۂ پاکستان (دو قومی نظریہ) نے برصغیر کے مسلمانوں کو ایک پلیٹ فارم پر متحد کیا اور ایک الگ وطن کے حصول کو ممکن بنایا۔"]},{"q":[["pak12-ch1-exercise-2",1]],"s":["دو قومی نظریہ کا مطلب ہے کہ برصغیر میں ہندو اور مسلمان دو الگ قومیں ہیں جن کے مذہب، تہذیب، رسم و رواج، تاریخ اور طرزِ زندگی مختلف ہیں۔","ارتقا: 712ء میں محمد بن قاسم کی آمد سے مسلمانوں کی الگ شناخت قائم ہوئی؛ مسلمان صوفیا اور علما (مجدد الف ثانی، شاہ ولی اللہ) نے مسلمانوں کے الگ تشخص کو اجاگر کیا۔","سرسید احمد خان پہلے ہندو مسلم اتحاد کے حامی تھے مگر ہندی اردو تنازع (1867ء) کے بعد انہوں نے کہا کہ ہندو اور مسلمان دو الگ قومیں ہیں؛ اس لیے انہیں دو قومی نظریے کا بانی کہا جاتا ہے۔","بعد میں جداگانہ انتخاب کا مطالبہ (1906ء)، علامہ اقبال کا خطبۂ الٰہ آباد (1930ء) اور قائدِاعظم کا یہ اعلان کہ مسلمان ہر لحاظ سے الگ قوم ہیں، اس نظریے کی منزلیں تھیں۔","اثرات: مسلمانوں میں سیاسی بیداری پیدا ہوئی، مسلم لیگ قائم ہوئی، قراردادِ لاہور (1940ء) منظور ہوئی اور بالآخر 1947ء میں برصغیر تقسیم ہو کر پاکستان وجود میں آیا۔"]},{"q":[["pak12-ch1-exercise-2",2]],"s":["1857ء کی جنگِ آزادی کے بعد مسلمان تعلیمی، معاشی اور سیاسی طور پر پسماندہ ہو گئے تھے؛ سرسید احمد خان نے ان کی اصلاح کے لیے علی گڑھ تحریک شروع کی۔","تعلیمی کردار: 1875ء میں علی گڑھ میں سکول اور 1877ء میں محمڈن اینگلو اورینٹل کالج قائم ہوا جہاں انگریزی کے ساتھ مشرقی و مغربی علوم پڑھائے جاتے تھے۔ 1886ء میں محمڈن ایجوکیشنل کانفرنس قائم کی گئی جس نے ملک بھر میں جدید تعلیم کو فروغ دیا۔","سیاسی کردار: سرسید نے دو قومی نظریہ پیش کیا اور مسلمانوں کو کانگریس سے دور رکھا؛ علی گڑھ کے فارغ التحصیل افراد نے مسلم لیگ کی بنیاد رکھنے اور اسے چلانے میں اہم کردار ادا کیا۔","سماجی کردار: تحریک نے مسلمانوں اور انگریزوں کے درمیان غلط فہمیاں دور کیں اور مسلمانوں میں خود اعتمادی، اتحاد اور قومی شعور پیدا کیا۔","یوں علی گڑھ تحریک نے ایک تعلیم یافتہ قیادت تیار کی جس نے تحریکِ پاکستان کی راہنمائی کی؛ اس لیے اسے قیامِ پاکستان کی بنیاد کہا جاتا ہے۔"]},{"q":[["pak12-ch1-exercise-2",3]],"s":["پسِ منظر: پہلی عالمی جنگ (1914ء) میں ترکی نے جرمنی کا ساتھ دیا۔ ترکی کے سلطان کو مسلمان خلیفہ مانتے تھے، اس لیے ہندوستانی مسلمان مشکل میں پڑ گئے۔ برطانیہ نے یقین دلایا کہ مقاماتِ مقدسہ اور خلافت کو نقصان نہیں پہنچے گا۔","جنگ کے بعد برطانیہ نے وعدہ خلافی کی اور سلطنتِ عثمانیہ کے ٹکڑے کر کے اتحادیوں میں بانٹ دیے، جس پر مسلمانوں نے تحریکِ خلافت شروع کی۔","22 ستمبر 1919ء کو آل انڈیا خلافت کمیٹی بنی؛ 23 نومبر 1919ء کو دہلی میں خلافت کانفرنس ہوئی۔ مولانا محمد علی جوہر اور مولانا شوکت علی نے تحریک کی قیادت کی؛ گاندھی نے ساتھ دیا اور تحریکِ عدم تعاون شروع کی۔","1922ء میں چوری چورا کے پرتشدد واقعے کے بعد گاندھی نے تحریکِ عدم تعاون ختم کر دی جس سے تحریکِ خلافت کمزور ہوئی، اور 1924ء میں ترکی میں مصطفیٰ کمال اتاترک نے خلافت ختم کر دی۔","اثرات: اگرچہ تحریک اپنا مقصد حاصل نہ کر سکی مگر مسلمانوں کو عوامی تحریک منظم کرنے کا تجربہ ہوا، نئی قیادت ابھری، ہندوؤں کی ذہنیت کا اندازہ ہوا اور مسلمانوں میں سیاسی بیداری اور اتحاد پیدا ہوا جو آگے چل کر تحریکِ پاکستان میں کام آیا۔"]},{"q":[["pak12-ch1-exercise-2",4]],"s":["کرپس مشن (1942ء) کی تجاویز: جنگ کے بعد ہندوستانی نمائندوں پر مشتمل آئین ساز اسمبلی بنے گی؛ ہندوستان کو ڈومینین کا درجہ ملے گا؛ جو صوبے وفاق میں شامل نہ ہونا چاہیں وہ الگ رہ سکیں گے؛ جنگ کے دوران دفاع برطانیہ کے پاس رہے گا۔","کابینہ مشن (1946ء) کی تجاویز: برطانوی ہند اور ریاستوں پر مشتمل کل ہند یونین بنے گی؛ صوبے تین گروپوں میں تقسیم ہوں گے (ایک ہندو اکثریتی اور دو مسلم اکثریتی)؛ دس سال بعد کوئی صوبہ اپنے گروپ سے الگ ہو سکے گا؛ مرکز میں عبوری حکومت بنے گی۔","موازنہ: کرپس تجاویز میں پاکستان کا ذکر صرف ضمنی طور پر صوبوں کے الگ رہنے کے حق میں تھا، جبکہ کابینہ مشن نے مسلم اکثریتی صوبوں کے الگ گروپ بنا کر مسلمانوں کو عملی طور پر خود مختاری کا موقع دیا۔","دونوں نے متحدہ ہندوستان کا تصور رکھا اور دونوں ناکام ہوئیں؛ کرپس تجاویز کو کانگریس اور مسلم لیگ دونوں نے مسترد کیا، جبکہ کابینہ مشن کو مسلم لیگ نے قبول کیا مگر کانگریس کی من مانی تعبیر کی وجہ سے یہ بھی ناکام ہوا۔","رائے: مسلمانوں کے لیے کابینہ مشن کی تجاویز بہتر تھیں، کیونکہ ان میں مسلم اکثریتی صوبوں کے گروپ، مرکز کے محدود اختیارات اور دس سال بعد علیحدگی کا حق دیا گیا تھا، جو عملاً پاکستان کی بنیاد فراہم کرتا تھا۔"]}]}},"2":{"lang":"ur","items":{"mcqs":[{"q":[["pak12-ch2-exercise-1",10]],"ob":1,"s":["قیامِ پاکستان کے بعد قائدِاعظم محمد علی جناح پاکستان کے پہلے گورنر جنرل بنے۔"],"c":2},{"q":[["pak12-ch2-exercise-1",11]],"ob":1,"s":["لیاقت علی خان پاکستان کے پہلے وزیرِاعظم تھے۔"],"c":1},{"q":[["pak12-ch2-exercise-1",12]],"ob":1,"s":["ضلع گورداسپور کی تحصیل بٹالہ کی آبادی 70 فیصد مسلمانوں پر مشتمل تھی اور جغرافیائی طور پر بھی پاکستان سے ملحق تھی، مگر اسے بھارت میں شامل کر دیا گیا۔"],"c":2},{"q":[["pak12-ch2-exercise-1",13]],"ob":1,"n":"سبق کے مطابق شکایت کانگریسی راہنماؤں (پنڈت نہرو وغیرہ) نے اٹھائی، مگر برطانوی حکومت سے انہیں ہٹوانے کا کام لارڈ ماؤنٹ بیٹن نے کیا۔","s":["آکن لیک نے افواج کی تقسیم تیزی اور انصاف سے کی تو کانگریسی راہنماؤں نے ان پر جانبداری کا الزام لگا کر شور مچایا۔","لارڈ ماؤنٹ بیٹن، جو پاکستان سے ذاتی ناراضی رکھتے تھے، برطانوی حکومت سے آکن لیک کا ہیڈکوارٹر بند کروانے اور انہیں انگلستان واپس بلوانے کے احکامات جاری کروانے میں کامیاب ہوئے۔"],"c":3},{"q":[["pak12-ch2-exercise-1",14]],"ob":1,"s":["ریڈکلف ایوارڈ کے تحت دریائے راوی پر مادھوپور اور دریائے ستلج پر فیروزپور کے ہیڈورکس بھارت کو دیے گئے جبکہ ان سے نکلنے والی نہریں پاکستان کے صوبہ پنجاب کو سیراب کرتی تھیں؛ اس لیے سب سے زیادہ پنجاب متاثر ہوا۔"],"c":1}],"objective":[{"q":[["pak12-ch2-exercise-1",2]],"s":["لارڈ ماؤنٹ بیٹن","لارڈ ماؤنٹ بیٹن 22 مارچ 1947ء کو ہندوستان پہنچے اور ہندوستان کے آخری وائسرائے تھے۔"],"a":"لارڈ ماؤنٹ بیٹن"},{"q":[["pak12-ch2-exercise-1",3]],"s":["پنڈت جواہر لال نہرو","پنڈت جواہر لال نہرو بھارت کے پہلے وزیرِاعظم تھے۔"],"a":"پنڈت جواہر لال نہرو"},{"q":[["pak12-ch2-exercise-1",4]],"s":["جسٹس محمد منیر","پنجاب باؤنڈری کمیشن میں پاکستان کی نمائندگی جسٹس دین محمد اور جسٹس محمد منیر نے کی۔"],"a":"جسٹس محمد منیر"},{"q":[["pak12-ch2-exercise-1",5]],"s":["750 (ملین روپے، یعنی 75 کروڑ)","باہمی گفت و شنید سے نقد اثاثوں میں پاکستان کا حصہ 750 ملین روپے مقرر ہوا۔"],"a":"750 (ملین روپے، یعنی 75 کروڑ)"},{"q":[["pak12-ch2-exercise-1",6]],"s":["3 جون (1947ء)","تقسیمِ ہند کا فیصلہ 3 جون 1947ء کے منصوبے کے تحت ہوا۔"],"a":"3 جون (1947ء)"},{"q":[["pak12-ch2-exercise-1",7]],"s":["19 ستمبر 1960ء","19 ستمبر 1960ء کو پنڈت نہرو اور فیلڈ مارشل ایوب خان نے سندھ طاس معاہدے پر دستخط کیے۔"],"a":"19 ستمبر 1960ء"},{"q":[["pak12-ch2-exercise-1",8]],"s":["قائدِاعظم محمد علی جناح","11 اگست 1947ء کو قائدِاعظم پاکستان کی پہلی دستور ساز اسمبلی کے صدر منتخب ہوئے اور اس کی صدارت کی۔"],"a":"قائدِاعظم محمد علی جناح"},{"q":[["pak12-ch2-exercise-2",1]],"tf":"tf","s":["غلط۔ تقسیمِ ہند کا منصوبہ (3 جون منصوبہ) لارڈ ماؤنٹ بیٹن نے پیش کیا۔ سر سیرل ریڈکلف دونوں باؤنڈری کمیشنوں کے سربراہ تھے اور انہوں نے سرحدوں کا فیصلہ (ریڈکلف ایوارڈ) دیا۔"],"c":1},{"q":[["pak12-ch2-exercise-2",2]],"tf":"tf","s":["درست۔ پٹھانکوٹ ضلع گورداسپور کی واحد ہندو اکثریتی تحصیل تھی؛ اسے مشرقی پنجاب میں شامل کرنے سے بھارت کو کشمیر تک پہنچنے کا زمینی راستہ مل گیا۔"],"c":0},{"q":[["pak12-ch2-exercise-2",3]],"tf":"tf","s":["درست۔ کلکتہ صوبہ بنگال کا دارالحکومت ہونے کے ساتھ صنعتی، تجارتی اور تعلیمی مرکز اور اہم بندرگاہ بھی تھا۔"],"c":0},{"q":[["pak12-ch2-exercise-2",4]],"tf":"tf","s":["غلط۔ پاکستان کو سرکاری ملازمین کی شدید کمی کا سامنا تھا؛ صرف 82 مسلمان اعلیٰ افسران پاکستان آئے جن میں سیکرٹری کے درجے کا صرف ایک افسر تھا۔"],"c":1},{"q":[["pak12-ch2-exercise-2",5]],"tf":"tf","s":["درست۔ گاندھی نے مرن بھرت (بھوک ہڑتال) کر کے بھارتی حکومت کو پاکستان کا جائز حصہ ادا کرنے پر مجبور کیا، اگرچہ نہرو اور پٹیل انہیں ٹالتے رہے۔"],"c":0}],"shortQuestions":[{"q":[["pak12-ch2-exercise-2",7]],"s":["پنجاب میں: ضلع گورداسپور (بالخصوص مسلم اکثریتی تحصیلیں گورداسپور اور بٹالہ، اور پٹھانکوٹ) اور ضلع فیروزپور کی تحصیلیں فیروزپور اور زیرہ مع فیروزپور ہیڈورکس۔","بنگال میں: کلکتہ شہر اور مسلم اکثریتی اضلاع مرشد آباد اور ندیا۔ یہ علاقے ناانصافی سے بھارت کو دیے جانے کی وجہ سے متنازعہ بن گئے۔"]},{"q":[["pak12-ch2-exercise-2",8]],"s":["کانگریسی راہنما اور متعصب ہندو چاہتے تھے کہ پاکستان اتنے مسائل میں الجھ جائے کہ گھبرا کر دوبارہ بھارت میں ضم ہونے پر مجبور ہو جائے؛ انگریزوں اور ہندوؤں کی ملی بھگت سے تقسیم بہت عجلت میں کی گئی۔","اس لیے پاکستان کو دارالحکومت، دفاتر اور ملازمین کی کمی، مہاجرین کی آمد، ریڈکلف ایوارڈ کی ناانصافیاں، اثاثوں اور فوجی سامان کی عدم ادائیگی، نہری پانی اور ریاستوں کے الحاق (کشمیر) جیسے مسائل کا سامنا کرنا پڑا۔"]},{"q":[["pak12-ch2-exercise-2",9]],"s":["گورداسپور مسلم اکثریتی ضلع تھا، مگر اس کی تحصیل پٹھانکوٹ کے ذریعے ہی بھارت کو کشمیر تک زمینی راستہ مل سکتا تھا۔","اسی لیے ماؤنٹ بیٹن اور ریڈکلف نے کانگریس سے ملی بھگت کر کے پورے ضلع کی آبادی کے اصول کو نظرانداز کیا اور ایوارڈ میں تبدیلی کر کے یہ علاقہ بھارت کو دے دیا۔"]},{"q":[["pak12-ch2-exercise-2",10]],"s":["آکن لیک نے افواج کی تقسیم کا پہلا مرحلہ 15 اگست 1947ء تک انصاف سے مکمل کر لیا تھا، جبکہ کانگریس چاہتی تھی کہ یہ کام دو سال لے اور پاکستان بغیر فوج کے رہے۔","منصوبہ ناکام ہوتے دیکھ کر کانگریسی راہنماؤں نے ان پر جانبداری کا الزام لگایا اور ماؤنٹ بیٹن نے برطانوی حکومت سے ان کا ہیڈکوارٹر بند کروا کر انہیں واپس بلوا لیا۔"]},{"q":[["pak12-ch2-exercise-2",11]],"s":["قائدِاعظم نے پشاور میں طلبہ سے خطاب کرتے ہوئے انہیں سب سے زیادہ تاکید کی کہ وہ اپنی پوری توجہ حصولِ علم پر مرکوز کریں اور ایجی ٹیشن کی سیاست سے مکمل طور پر دور رہیں، کیونکہ اسی میں پاکستان کی بقا اور خوشحالی ہے۔"]}],"longQuestions":[{"q":[["pak12-ch2-exercise-2",12]],"s":["تاریخی پسِ منظر: 1941ء کی مردم شماری کے مطابق ریاست جموں و کشمیر کی 77 فیصد آبادی مسلمان تھی۔ ہندو مہاراجہ ہری سنگھ نے عوام کی مرضی کے خلاف ریاست کو آزاد رکھنا چاہا اور مسلمانوں پر تشدد کیا؛ کشمیری مسلمانوں نے بغاوت کی اور قبائلی مجاہدین ان کی مدد کو آئے۔","مہاراجہ نے اکتوبر 1947ء میں بھارت سے الحاق کی مبینہ دستاویز پر دستخط کیے اور بھارت نے فوجیں اتار دیں؛ 1948ء میں پاکستانی افواج کو آزاد کشمیر کے تحفظ کے لیے بھیجنا پڑا۔","جنوری 1948ء میں بھارت خود یہ مسئلہ سلامتی کونسل میں لے گیا، جہاں طے ہوا کہ کشمیر کے مستقبل کا فیصلہ اس کے باشندے آزادانہ استصوابِ رائے سے کریں گے؛ دونوں ملکوں نے یہ قرارداد تسلیم کی مگر بھارت نے آج تک اس پر عمل نہیں کیا۔ بعد میں 1965ء کی جنگ، کارگل اور 2019ء میں بھارت کی طرف سے کشمیر کی خصوصی حیثیت کے خاتمے نے مسئلے کو مزید سنگین بنا دیا۔","ممکنہ حل: (1) اقوامِ متحدہ کی قراردادوں کے مطابق اقوامِ متحدہ کی نگرانی میں آزادانہ اور غیر جانبدارانہ استصوابِ رائے؛ (2) پاکستان، بھارت اور کشمیری قیادت کے درمیان سنجیدہ اور بامعنی مذاکرات؛ (3) علاقے سے افواج کی واپسی اور انسانی حقوق کا تحفظ؛ (4) عالمی برادری اور بین الاقوامی اداروں کی ثالثی۔","پائیدار حل وہی ہو سکتا ہے جو کشمیری عوام کی خواہشات کے مطابق ہو، کیونکہ حقِ خود ارادیت ان کا بنیادی حق ہے اور خطے کا امن اسی سے وابستہ ہے۔"]},{"q":[["pak12-ch2-exercise-2",13]],"s":["تنازع کی وجہ: ریڈکلف ایوارڈ نے پنجاب کو ناانصافی سے تقسیم کیا اور دریائے راوی پر مادھوپور اور ستلج پر فیروزپور کے ہیڈورکس بھارت کو دے دیے، حالانکہ ان سے نکلنے والی نہریں پاکستانی علاقوں کو سیراب کرتی تھیں۔","بھارت نے یکم اپریل 1948ء کو ان نہروں کا پانی بند کر دیا تاکہ پنجاب کی سرسبز زمین بنجر ہو جائے؛ پاکستان کو عارضی معاہدے کے تحت پانی بحال کروانا پڑا۔","پاکستان نے مستقل حل کے لیے اقوامِ متحدہ سے رجوع کیا؛ عالمی بینک کے صدر نے ثالثی کی پیشکش کی جسے 1952ء میں دونوں ملکوں نے قبول کیا۔","طویل مذاکرات کے بعد 19 ستمبر 1960ء کو پنڈت نہرو اور فیلڈ مارشل ایوب خان نے سندھ طاس معاہدے اور سندھ طاس ترقیاتی فنڈ کے معاہدے پر دستخط کیے: مغربی دریا (سندھ، جہلم، چناب) پاکستان کے لیے اور مشرقی دریا (راوی، بیاس، ستلج) بھارت کے لیے مخصوص ہوئے۔","اس معاہدے کے تحت پاکستان نے ترقیاتی فنڈ کی مدد سے منگلا اور تربیلا ڈیم، بیراج اور رابطہ نہریں تعمیر کیں تاکہ مشرقی دریاؤں کے پانی کی کمی پوری ہو؛ معاملات کی نگرانی کے لیے مستقل انڈس کمیشن قائم ہوا۔"]},{"q":[["pak12-ch2-exercise-2",14]],"s":["قائدِاعظم نے بطور پہلے گورنر جنرل انتہائی مشکل حالات میں بے مثال قیادت کی۔","مہاجرین کی آباد کاری: تقریباً 65 لاکھ مہاجرین کے لیے قائدِاعظم ریلیف فنڈ قائم کیا، اکتوبر 1947ء میں خود لاہور جا کر انتظامات کا جائزہ لیا اور قوم سے مہاجر بھائیوں کی مدد کی اپیل کی۔","انتظامیہ اور معیشت: سرکاری ملازمین کو ہدایت کی کہ وہ حکمران نہیں بلکہ قوم کے خادم بن کر سیاست سے الگ رہ کر کام کریں؛ اسٹیٹ بینک کا افتتاح کر کے اسلامی اصولوں پر معاشی نظام کی راہنمائی دی۔","قومی یکجہتی: صوبائی اور نسلی تعصب سے بچنے کی تلقین کی (ہم سب پاکستانی ہیں)، اقلیتوں کو برابر کے حقوق کی ضمانت دی (11 اگست 1947ء کی تقریر) اور ایمان، اتحاد، تنظیم کا نعرہ دیا۔","خارجہ پالیسی اور دفاع: تمام ممالک سے دوستانہ تعلقات، انصاف اور امن پر مبنی خارجہ پالیسی کے اصول وضع کیے؛ کشمیر اور دفاعی مسائل پر جرأت مندانہ مؤقف اپنایا۔ شدید علالت کے باوجود 11 ستمبر 1948ء تک انتھک کام کر کے نوزائیدہ مملکت کو قدموں پر کھڑا کیا۔"]},{"q":[["pak12-ch2-exercise-2",15]],"s":["خلوص اور دیانت: اچھا راہنما اپنے کام، ملک اور قوم سے مخلص ہوتا ہے اور اپنی ذاتی، خاندانی اور گروہی مفادات کو قومی مفاد کے تابع رکھتا ہے۔","انصاف اور قانون کی پاسداری: وہ سرکاری فرائض انصاف کے اصولوں کے مطابق ادا کرتا ہے اور خود بھی قانون کا احترام کرتا ہے۔","بصیرت اور فیصلہ سازی: وہ دور اندیش ہوتا ہے، مشکل حالات میں جرأت سے بروقت فیصلے کرتا ہے۔","مکالمہ اور لچک: وہ کھلے ذہن سے بات چیت کے لیے تیار رہتا ہے اور ضرورت پڑنے پر قومی مفاد میں رعایت دیتا ہے۔","ایمان، اتحاد اور تنظیم: وہ قوم میں یقینِ محکم، اتحاد اور نظم و ضبط پیدا کرتا ہے، علم رکھتا ہے، اچھا مقرر اور عملی نمونہ ہوتا ہے — جیسے قائدِاعظم محمد علی جناح۔"]},{"q":[["pak12-ch2-exercise-2",16]],"s":["دنیا میں ہر مسئلے کا حل مذاکرات میں پوشیدہ ہے؛ قوموں کے تنازعات کا بہترین حل پُرامن ذرائع ہیں: براہِ راست بات چیت، ثالثی، مصالحت اور عالمی عدالتِ انصاف جیسے بین الاقوامی اداروں سے رجوع۔","اقوامِ متحدہ کے منشور اور بین الاقوامی قانون کا احترام، اور کیے گئے معاہدوں کی پابندی (جیسے عالمی بینک کی ثالثی سے سندھ طاس معاہدہ) پائیدار امن کی ضمانت ہیں۔","اعتماد سازی کے اقدامات: تجارت، ثقافتی و تعلیمی روابط، عوامی رابطے اور سرحدی تنازعات میں تحمل۔","موجودہ عالمی تناظر میں ایٹمی ہتھیاروں، دہشت گردی، موسمیاتی تبدیلی اور معاشی باہمی انحصار کی وجہ سے جنگ کسی مسئلے کا حل نہیں؛ تعاون ہی سب کے مفاد میں ہے۔","اسلام بھی صلح، عدل اور عہد کی پاسداری کی تعلیم دیتا ہے۔ میری رائے میں انصاف پر مبنی مذاکرات اور متعلقہ عوام کی خواہشات کا احترام (جیسے کشمیر میں استصوابِ رائے) ہی تنازعات کا بہترین حل ہے۔"]}]}},"3":{"lang":"ur","items":{"mcqs":[{"q":[["pak12-ch3-exercise-1",15]],"ob":1,"s":["ننکانہ صاحب سکھ مذہب کے بانی بابا گرو نانک کی جائے پیدائش ہے، اس لیے یہ سکھوں کا مقدس مقام ہے۔"],"c":1},{"q":[["pak12-ch3-exercise-1",16]],"ob":1,"s":["بلوچستان کو پاکستان کا پھلوں کا باغ کہا جاتا ہے؛ یہاں سیب، انگور، چیری، خوبانی اور بادام وغیرہ کثرت سے پیدا ہوتے ہیں اور یہ ملک کے تقریباً 45 فیصد پھل مہیا کرتا ہے۔"],"c":3},{"q":[["pak12-ch3-exercise-1",17]],"ob":1,"s":["ہر طول بلد سورج کے سامنے سے گزرنے میں چار منٹ لیتا ہے، اس لیے دو طول بلد کے درمیان وقت کا فرق چار منٹ ہوتا ہے۔"],"c":1},{"q":[["pak12-ch3-exercise-2",0]],"ob":1,"s":["ثقافتی نقشے انسانوں سے متعلق معلومات مثلاً مذاہب، قبائل، زبانوں اور آبادی کی تقسیم، ملکوں کی تقسیم یا تاریخی واقعات پیش کرتے ہیں۔"],"c":2},{"q":[["pak12-ch3-exercise-2",1]],"ob":1,"s":["پاکستان کے جنوب میں بحیرۂ عرب ہے جو بحرِ ہند کا شمالی حصہ ہے۔"],"c":0}],"objective":[{"q":[["pak12-ch3-exercise-1",2]],"s":["تاجکستان","شمال میں افغانستان کا علاقہ واخان کی پٹی پاکستان کو تاجکستان سے جدا کرتی ہے۔"],"a":"تاجکستان"},{"q":[["pak12-ch3-exercise-1",3]],"s":["انڈونیشیا","اسلامی دنیا مغرب میں مراکش سے مشرق میں انڈونیشیا تک پھیلی ہوئی ہے اور پاکستان اس کے وسط میں واقع ہے۔"],"a":"انڈونیشیا"},{"q":[["pak12-ch3-exercise-1",4]],"s":["شاہراہِ قراقرم","چین کے ساتھ تجارت اور آمد و رفت شاہراہِ قراقرم (درۂ خنجراب) کے ذریعے ہوتی ہے۔"],"a":"شاہراہِ قراقرم"},{"q":[["pak12-ch3-exercise-1",5]],"s":["تھل","دریائے سندھ اور دریائے جہلم کے درمیان ریتلے علاقے کو تھل کہتے ہیں۔"],"a":"تھل"},{"q":[["pak12-ch3-exercise-1",6]],"s":["سیاحت","دوسری عالمی جنگ کے بعد سیاحت کو باقاعدہ صنعت کا درجہ دیا گیا؛ پاکستان نے اسے 1970ء میں صنعت قرار دیا۔"],"a":"سیاحت"},{"q":[["pak12-ch3-exercise-1",7]],"s":["تین","پیمانہ عام طور پر تین طریقوں سے ظاہر کیا جاتا ہے: بیان کے ذریعے، کسر (نسبتی کسر) کے ذریعے اور خطی (ترسیمی) پیمانے کے ذریعے۔"],"a":"تین"},{"q":[["pak12-ch3-exercise-1",9]],"tf":"tf","s":["درست۔ پاکستان کے جنوب میں بحیرۂ عرب واقع ہے۔"],"c":0},{"q":[["pak12-ch3-exercise-1",10]],"tf":"tf","s":["غلط۔ پاکستان اسلامی دنیا کے آخری کنارے پر نہیں بلکہ اس کے وسط میں واقع ہے جو مراکش سے انڈونیشیا تک پھیلی ہوئی ہے۔"],"c":1},{"q":[["pak12-ch3-exercise-1",11]],"tf":"tf","s":["درست۔ گرمیوں میں سبی اور جیکب آباد میں درجۂ حرارت 50 ڈگری سیلسیس تک پہنچ جاتا ہے؛ یہ دنیا کے گرم ترین مقامات میں شمار ہوتے ہیں۔"],"c":0},{"q":[["pak12-ch3-exercise-1",12]],"tf":"tf","s":["غلط۔ کے ٹو (8611 میٹر) دنیا کی دوسری بلند ترین چوٹی ہے؛ دنیا کی بلند ترین چوٹی ماؤنٹ ایورسٹ ہے۔"],"c":1},{"q":[["pak12-ch3-exercise-1",13]],"tf":"tf","s":["غلط۔ شاہراہِ قراقرم کو دنیا کا آٹھواں عجوبہ کہا جاتا ہے، ساتواں نہیں۔"],"c":1},{"q":[["pak12-ch3-exercise-2",8]],"d":"pak12-ch3-match","s":["درست جوڑ:","مرغزار — وادیٔ سوات۔","بدھا کی چٹان — وادیٔ گلگت۔","قلعہ میر مغلشت — وادیٔ چترال۔","دنیا کا آٹھواں عجوبہ — شاہراہِ قراقرم۔","جھیل سیف الملوک — وادیٔ کاغان۔"]}],"shortQuestions":[{"q":[["pak12-ch3-exercise-2",3]],"s":["وسطی ایشیا کی مسلمان ریاستیں: قازقستان، ازبکستان، ترکمانستان، کرغیزستان اور تاجکستان (آذربائیجان بھی ان خشکی میں گھرے مسلمان ممالک میں شامل ہے)۔"]},{"q":[["pak12-ch3-exercise-2",4]],"s":["مغربی پہاڑی سلسلے میں ترتیب وار (شمال سے جنوب) یہ پہاڑ شامل ہیں:","1۔ شندور یا ہندو راج (ہندوکش)، 2۔ دیر، سوات اور سندھ کوہستان، 3۔ کوہِ سفید، 4۔ وزیرستان کے پہاڑ، 5۔ کوہِ سلیمان، 6۔ کوہِ کھیرتھر۔"]},{"q":[["pak12-ch3-exercise-2",5]],"s":["اگر نقشے پر سمت کا نشان نہ ہو تو مسلمہ اصول کے مطابق نقشے کا اوپر والا حصہ شمال، نیچے والا جنوب، دائیں جانب مشرق اور بائیں جانب مغرب ہوتا ہے۔","نیز طول بلد کی لکیریں شمالاً جنوباً اور عرض بلد کی لکیریں شرقاً غرباً ہوتی ہیں؛ ان کی مدد سے بھی سمت معلوم کی جا سکتی ہے۔"]},{"q":[["pak12-ch3-exercise-2",6]],"s":["پیمانے کے لحاظ سے نقشے تین قسم کے ہیں:","1۔ علاقائی نقشہ (چھوٹا پیمانہ) — دنیا، براعظموں اور ملکوں کی عمومی معلومات۔ 2۔ ٹوپوگرافیکل نقشہ (بڑا پیمانہ) — بلندی، دریا، جنگلات، شہر، سڑکیں تفصیل سے۔ 3۔ کیڈسٹرل نقشہ (بہت بڑا پیمانہ) — دیہات اور کھیتوں کی حدود تک؛ مالیہ اور کان کنی کے لیے۔"]},{"q":[["pak12-ch3-exercise-2",7]],"s":["آب و ہوا کے لحاظ سے پاکستان کے خطے:","1۔ سرد آب و ہوا والا شمالی اور شمال مغربی پہاڑی خطہ؛ 2۔ شدید آب و ہوا والا شمالی میدانی خطہ؛ 3۔ زیریں وادیٔ سندھ اور صحرائے تھر کا خطہ؛ 4۔ براعظمی آب و ہوا والا سطح مرتفع بلوچستان؛ 5۔ بحری آب و ہوا والا ساحلی خطہ۔"]}],"longQuestions":[{"q":[["pak12-ch3-exercise-2",9]],"s":["پاکستان جغرافیائی اور سیاسی لحاظ سے ایشیا کے مرکز اور دنیا کے انتہائی حساس خطے میں واقع ہے، اس لیے بین الاقوامی سیاست میں ہمیشہ خصوصی توجہ کا مرکز رہا ہے۔","ہمسایہ ممالک: شمال مشرق میں چین (عالمی طاقت)، مشرق میں بھارت (کشمیر کا تنازع، دو ایٹمی طاقتیں)، شمال مغرب میں افغانستان (طویل جنگیں) اور مغرب میں ایران؛ واخان کی پٹی کے پار وسطی ایشیا۔","وسطی ایشیا کا دروازہ: وسطی ایشیا کی خشکی میں گھری ریاستوں اور افغانستان کو سمندر تک رسائی پاکستان کی بندرگاہوں (کراچی، گوادر) کے ذریعے آسانی سے مل سکتی ہے؛ شاہراہِ قراقرم اور سی پیک چین کو بحیرۂ عرب سے ملاتے ہیں۔","بحیرۂ عرب اور بحرِ ہند: یہ عالمی بحری اور فضائی راستوں پر واقع ہے اور خلیج فارس سے تیل کی ترسیل کے راستے کے قریب ہے؛ توانائی کی پائپ لائنیں (وسطی ایشیا، قطر اور ایران سے بھارت تک) اس کی سرزمین سے گزر سکتی ہیں۔","اسلامی دنیا کے وسط میں واقع ہونے، ایٹمی طاقت ہونے اور بڑی طاقتوں کے مفادات کے سنگم پر ہونے کی وجہ سے پاکستان کی اہمیت مزید بڑھ جاتی ہے۔"]},{"q":[["pak12-ch3-exercise-2",10]],"s":["کسی علاقے کے طبعی خدوخال اور آب و ہوا وہاں کی آبادی، معیشت اور رہن سہن کو براہِ راست متاثر کرتے ہیں۔","پہاڑی علاقے: سخت سردی، کم زرعی زمین؛ آبادی کم، لوگ محنتی، گلہ بانی، جنگلات، باغبانی اور سیاحت ذریعۂ معاش؛ سردیوں میں روزگار کے لیے میدانی علاقوں کی طرف نقل مکانی۔","میدانی علاقے: زرخیز زمین، پانی اور موزوں آب و ہوا کی وجہ سے زراعت، گنجان آبادی، بڑے شہر، صنعتیں اور ذرائع آمد و رفت ترقی یافتہ۔","صحرائی علاقے (تھر، تھل، چولستان): پانی کی کمی، کم آبادی، خانہ بدوشی اور مویشی پالنا؛ بلوچستان میں کاریز کے ذریعے آبپاشی۔","ساحلی علاقے: معتدل اور مرطوب آب و ہوا، ماہی گیری، بندرگاہیں، تجارت اور صنعتیں (نمی کی وجہ سے کراچی میں سوتی کپڑے کے کارخانے)۔ آب و ہوا لباس، خوراک، مکانات کی بناوٹ، صحت، فصلوں اور تہواروں تک کو متاثر کرتی ہے۔"]},{"q":[["pak12-ch3-exercise-2",11]],"s":["پاکستان کی آب و ہوا ہر جگہ یکساں نہیں کیونکہ: (1) یہ 24° سے 37° شمالی عرض بلد تک پھیلا ہوا ہے؛ (2) اس کے 60 فیصد رقبے پر پہاڑ اور سطح مرتفع ہیں جبکہ باقی میدان اور صحرا ہیں، اس لیے بلندی میں بہت فرق ہے؛ (3) زیادہ تر حصہ سمندر سے دور ہے جبکہ جنوب میں ساحل ہے؛ (4) مون سون اور مغربی ہواؤں سے بارش کی مقدار مختلف ہے۔","تقابلی جائزہ — شمالی پہاڑی خطہ: سردیوں میں شدید سردی، برف باری، درجۂ حرارت نقطۂ انجماد سے نیچے، گرمیاں خوشگوار؛ تجارت اور زراعت سردیوں میں رک جاتی ہے؛ لوگ گرم لباس پہنتے اور پتھر و لکڑی کے مکان بناتے ہیں۔","ساحلی خطہ: سمندر کے قریب ہونے کی وجہ سے آب و ہوا معتدل اور مرطوب، نہ زیادہ گرمی نہ زیادہ سردی؛ سال بھر کاروبار جاری رہتا ہے؛ ماہی گیری، تجارت اور صنعتیں؛ ناریل اور پام کے درخت۔","یوں ایک خطے میں موسم کی شدت معاشی سرگرمیوں کو محدود کرتی ہے جبکہ دوسرے میں معتدل موسم سال بھر سرگرمیوں کو ممکن بناتا ہے۔"]},{"q":[["pak12-ch3-exercise-2",12]],"s":["پاکستان کا شمار دنیا کے ان چند ممالک میں ہوتا ہے جہاں سیاحوں کے لیے فلک بوس برف پوش پہاڑ، گلیشیئر، خوبصورت جھیلیں، جنگلات سے ڈھکی وادیاں، تاریخی مقامات، نادر آثار، رنگا رنگ روایات، میلے اور نیلگوں ساحلِ سمندر سب کچھ موجود ہے۔","شمالی علاقہ جات: کے ٹو، نانگا پربت، گلیشیئر، وادیٔ گلگت (بدھا کی چٹان، شندور جھیل)، ہنزہ، چترال (قلعہ میر مغلشت، کالاش وادیاں، گرم چشمہ)، کاغان (ناران، شوگران، جھیل سیف الملوک)، سوات (مرغزار، کالام)۔","تاریخی اور مذہبی مقامات: موہنجو دڑو، ہڑپہ، ٹیکسلا (گندھارا تہذیب)، لاہور کے مغلیہ آثار، مکلی، ننکانہ صاحب (سکھ) وغیرہ۔","شاہراہِ قراقرم (دنیا کا آٹھواں عجوبہ)، صحرا، ساحلی علاقے اور ثقافتی تہوار (شندور پولو میلہ) بھی سیاحوں کو اپنی طرف کھینچتے ہیں۔","حکومت نے 1970ء میں سیاحت کو صنعت کا درجہ دیا اور سہولیات کے لیے ادارہ قائم کیا؛ اس لیے بجا طور پر پاکستان کو سیاحوں کی جنت کہا جاتا ہے۔"]},{"q":[["pak12-ch3-exercise-2",13]],"s":["پیمانہ: زمین اور نقشے پر فاصلوں کی نسبت بتاتا ہے (مثلاً 1 سینٹی میٹر = 1 کلومیٹر)؛ اس کے بغیر نقشے سے اصل فاصلے، رقبے اور سائز معلوم نہیں ہو سکتے۔ پیمانہ بیان، کسر اور خطی طریقے سے ظاہر کیا جاتا ہے۔","طول بلد اور عرض بلد: یہ فرضی لکیریں ہیں جن کی مدد سے دنیا کے کسی بھی مقام کا درست محلِ وقوع متعین کیا جاتا ہے؛ ان سے سمتیں معلوم ہوتی ہیں اور طول بلد سے وقت کا فرق (ہر درجے پر 4 منٹ) معلوم ہوتا ہے؛ اٹلس میں شہروں کو انہی کی مدد سے تلاش کیا جاتا ہے۔","روایتی علامات: دریا، سڑکیں، ریلوے لائنیں، شہر، سرحدیں، پہاڑ وغیرہ مخصوص علامات اور رنگوں سے دکھائے جاتے ہیں؛ اس طرح تھوڑی جگہ میں بہت سی معلومات واضح طور پر پیش ہو جاتی ہیں اور ہر شخص نقشہ آسانی سے سمجھ لیتا ہے۔","اس لیے پیمانہ، طول بلد و عرض بلد اور روایتی علامات کے بغیر نقشہ نامکمل اور ناقابلِ استعمال ہوتا ہے۔"]}]}},"4":{"lang":"ur","items":{"mcqs":[{"q":[["pak12-ch4-exercise",8]],"ob":1,"s":["قراردادِ مقاصد کی تیاری میں سب سے اہم کردار مولانا شبیر احمد عثمانی نے ادا کیا، جو دستور ساز اسمبلی کے رکن تھے۔"],"c":3},{"q":[["pak12-ch4-exercise",9]],"ob":1,"s":["چوہدری محمد علی کی وزارتِ عظمیٰ میں دستور ساز اسمبلی کی منظوری کے بعد پاکستان کا پہلا آئین 23 مارچ 1956ء کو نافذ ہوا۔"],"c":3},{"q":[["pak12-ch4-exercise",10]],"ob":1,"s":["1962ء کا آئین صدارتی طرز کا تھا جو صدر ایوب خان نے نافذ کیا؛ اس میں وزیرِاعظم کا عہدہ نہیں تھا۔ (1935ء کا ایکٹ پاکستان کا آئین نہیں بلکہ عبوری آئین تھا۔)"],"c":2},{"q":[["pak12-ch4-exercise",11]],"ob":1,"s":["1973ء کے آئین میں پہلی بار اسلام کو پاکستان کا \"سرکاری مذہب\" قرار دیا گیا۔"],"c":3},{"q":[["pak12-ch4-exercise",12]],"ob":1,"s":["20 جون 1980ء کو زکوٰۃ آرڈیننس نافذ کیا گیا جس کے تحت زکوٰۃ و عشر کی وصولی اور تقسیم کے لیے زکوٰۃ کمیٹیاں قائم ہوئیں۔"],"c":0}],"objective":[{"q":[["pak12-ch4-exercise",2]],"s":["1948ء","اقوامِ متحدہ کی جنرل اسمبلی نے 10 دسمبر 1948ء کو انسانی حقوق کا عالمی منشور منظور کیا۔"],"a":"1948ء"},{"q":[["pak12-ch4-exercise",3]],"s":["لیاقت علی خان","وزیرِاعظم لیاقت علی خان نے مارچ 1949ء میں دستور ساز اسمبلی میں قراردادِ مقاصد پیش کی جو 12 مارچ 1949ء کو منظور ہوئی۔"],"a":"لیاقت علی خان"},{"q":[["pak12-ch4-exercise",4]],"s":["1956ء (23 مارچ)","پاکستان کا پہلا آئین 23 مارچ 1956ء کو نافذ ہوا۔"],"a":"1956ء (23 مارچ)"},{"q":[["pak12-ch4-exercise",5]],"s":["لفظ \"مسلمان\"","1973ء کے آئین میں پہلی بار لفظ \"مسلمان\" کی واضح تعریف کی گئی (1974ء کی ترمیم سے مزید وضاحت ہوئی)۔"],"a":"لفظ \"مسلمان\""},{"q":[["pak12-ch4-exercise",6]],"s":["1981ء","بینکوں میں جنوری 1981ء سے بلاسود بینکاری کا نظام شروع کیا گیا اور نفع و نقصان میں شراکت کی بنیاد پر کھاتے کھولنے کا انتظام ہوا۔"],"a":"1981ء"},{"q":[["pak12-ch4-exercise",14]],"tf":"tf","s":["درست۔ قیامِ پاکستان کے بعد آئین سازی کا کام کئی سال تک التوا کا شکار رہا؛ عبوری طور پر 1935ء کا ایکٹ نافذ رہا اور پہلا آئین 1956ء میں بنا۔"],"c":0},{"q":[["pak12-ch4-exercise",15]],"tf":"tf","s":["درست۔ 1956ء کے آئین میں صرف سربراہِ مملکت (صدر) کے لیے مسلمان ہونا ضروری قرار دیا گیا تھا، وزیرِاعظم کے لیے یہ شرط نہیں رکھی گئی تھی۔"],"c":0},{"q":[["pak12-ch4-exercise",16]],"tf":"tf","s":["درست (سبق کے مطابق)۔ اپریل 1979ء کی تعلیمی پالیسی میں تعلیمی اداروں میں اسلامیات اور مطالعۂ پاکستان کو لازمی مضامین کا درجہ دیا گیا۔"],"c":0},{"q":[["pak12-ch4-exercise",17]],"tf":"tf","s":["غلط۔ 1973ء کے آئین کے مطابق سرکاری ملازمین کے علاوہ تمام پاکستانیوں کو سیاست میں حصہ لینے کا حق ہے؛ سرکاری ملازمین براہِ راست سیاست میں حصہ نہیں لے سکتے۔"],"c":1},{"q":[["pak12-ch4-exercise",18]],"tf":"tf","s":["درست۔ انسانی مساوات، جان و مال کا تحفظ، غلامی کا خاتمہ، خواتین کے حقوق اور قانون کی حکمرانی جیسے بہت سے حقوق دونوں میں مشترک ہیں؛ اقوامِ متحدہ کے منشور کے اکثر حقوق اسلامی تعلیمات کے عین مطابق ہیں۔"],"c":0}],"shortQuestions":[{"q":[["pak12-ch4-exercise",20]],"s":["قراردادِ مقاصد کے مطابق ساری کائنات پر حاکمیتِ اعلیٰ صرف اللہ تعالیٰ کی ہے اور اس میں کوئی اس کا شریک نہیں۔","پاکستان کے عوام کے پاس اختیارِ حاکمیت ایک مقدس امانت ہے جسے وہ قرآن و سنت کی حدود کے اندر رہ کر اپنے منتخب نمائندوں کے ذریعے استعمال کریں گے۔"]},{"q":[["pak12-ch4-exercise",21]],"s":["اسلامی نظریاتی کونسل اسلامی قانون و شریعت کے ماہرین پر مشتمل ہے۔","اس کے فرائض: قانون ساز اداروں کی راہنمائی کرنا کہ قوانین کو اسلامی تعلیمات کے مطابق کیسے ڈھالا جائے؛ حکومت کو موجودہ قوانین میں اسلام کے منافی امور سے آگاہ کرنا اور ان کی اصلاح کی سفارشات دینا؛ اور مسلمانوں کو اسلامی اصولوں کے مطابق زندگی گزارنے کے لیے تجاویز دینا۔"]},{"q":[["pak12-ch4-exercise",22]],"s":["1973ء کے آئین میں پہلی بار لفظ \"مسلمان\" کی واضح تعریف کی گئی: مسلمان وہ ہے جو اللہ تعالیٰ کی وحدانیت، حضرت محمد ﷺ کے آخری نبی (خاتم النبیین) ہونے اور قرآن و آخرت پر ایمان رکھتا ہو۔","جو شخص حضور ﷺ کے خاتم النبیین ہونے پر ایمان نہیں رکھتا وہ دائرۂ اسلام سے خارج ہے؛ 1974ء کی ترمیم کے ذریعے اس کی مزید وضاحت کی گئی۔"]},{"q":[["pak12-ch4-exercise",23]],"s":["آپ ﷺ نے خطبۂ حجۃ الوداع میں غلاموں سے اچھے سلوک کی تلقین فرمائی اور فرمایا کہ انہیں وہی کھلاؤ جو تم خود کھاتے ہو اور وہی پہناؤ جو تم خود پہنتے ہو۔","آپ ﷺ نے غلاموں کے ساتھ سختی سے پیش آنے سے بھی منع فرمایا۔"]},{"q":[["pak12-ch4-exercise",24]],"s":["آپ ﷺ نے فرمایا کہ مردوں کے عورتوں پر اور عورتوں کے مردوں پر حقوق ہیں۔","آپ ﷺ نے تاکید فرمائی کہ مرد اپنی عورتوں کے حقوق کا خیال رکھیں اور ان کے ساتھ نرمی اور حسنِ سلوک سے پیش آئیں۔"]}],"longQuestions":[{"q":[["pak12-ch4-exercise",25]],"s":["قراردادِ مقاصد مارچ 1949ء میں لیاقت علی خان نے دستور ساز اسمبلی میں پیش کی؛ اس میں طے کیا گیا کہ پاکستان کا آئین قرآن و سنت کی تعلیمات کے مطابق ہوگا۔","نکات: اللہ تعالیٰ کی حاکمیتِ اعلیٰ؛ عوام کے منتخب نمائندوں کے ذریعے اسلامی اصولوں کے مطابق جمہوریت، آزادی، مساوات، رواداری اور سماجی انصاف؛ انفرادی و اجتماعی زندگی میں اسلامی تعلیمات کا فروغ؛ اقلیتوں اور بنیادی حقوق کا تحفظ؛ وفاقی طرزِ حکومت اور صوبائی خود مختاری؛ عدلیہ کی آزادی۔","اہمیت: اس قرارداد نے آئین کی نوعیت کے بارے میں جاری متنازعہ بحث ختم کر دی اور واضح کر دیا کہ پاکستانی آئین اور معاشرے کی بنیاد اسلامی تعلیمات ہوں گی؛ یہ تمام مکاتبِ فکر کے علما کی تجاویز پر مبنی ہونے کی وجہ سے قومی اتفاقِ رائے کا اظہار تھی۔","اسی لیے اسے 1956ء، 1962ء اور 1973ء کے تمام آئینوں کے شروع میں دیباچے کے طور پر شامل کیا گیا۔","دیباچہ آئین کا قابلِ نفاذ حصہ نہیں ہوتا، اس لیے اسے مؤثر بنانے کے لیے 1985ء میں آٹھویں ترمیم کے ذریعے قراردادِ مقاصد کو آئین کا باقاعدہ حصہ (آرٹیکل 2-الف) بنا دیا گیا تاکہ آئین کی اسلامی بنیاد قانونی طور پر نافذ ہو سکے۔"]},{"q":[["pak12-ch4-exercise",26]],"s":["قراردادِ مقاصد کو دیباچے کے طور پر شامل کیا گیا اور اللہ تعالیٰ کی حاکمیت کا تصور برقرار رکھا گیا۔","ملک کا نام اسلامی جمہوریۂ پاکستان رکھا گیا اور اسلام کو پہلی بار سرکاری مذہب قرار دیا گیا۔","صدر اور وزیرِاعظم دونوں کے لیے مسلمان ہونا لازمی قرار دیا گیا اور پہلی بار لفظ \"مسلمان\" کی تعریف کی گئی۔","اسلامی نظریاتی کونسل کے قیام کا ذکر کیا گیا تاکہ قوانین کو اسلامی تعلیمات کے مطابق ڈھالا جائے؛ قرآن و سنت کے منافی کوئی قانون نہیں بنایا جائے گا۔","اسلامی اقدار کا تحفظ، سود اور برائیوں کا خاتمہ، قرآن و اسلامیات کی تعلیم کا فروغ اور اسلامی ممالک سے برادرانہ تعلقات کا عزم بھی آئین کا حصہ ہے۔"]},{"q":[["pak12-ch4-exercise",27]],"s":["اقوامِ متحدہ نے 10 دسمبر 1948ء کو انسانی حقوق کا عالمی منشور منظور کیا، جبکہ نبی کریم ﷺ نے چودہ سو سال پہلے خطبۂ حجۃ الوداع میں انسانی حقوق کا جامع منشور پیش فرمایا۔","مماثلت: (1) انسانی مساوات — خطبے میں رنگ و نسل کے امتیاز کے بغیر سب انسان برابر؛ منشور میں رنگ، نسل، قومیت اور مذہب کے امتیاز کے بغیر مساوی حقوق۔ (2) جان، مال اور عزت کا تحفظ دونوں میں۔","(3) غلامی اور ظلم کا خاتمہ — خطبے میں غلاموں سے حسنِ سلوک؛ منشور میں غلامی اور جبری مشقت کی ممانعت۔ (4) خواتین کے حقوق اور وراثت میں حصہ۔ (5) قانون کی نظر میں برابری اور حکمرانوں و رعایا کے حقوق۔","فرق: خطبۂ حجۃ الوداع کے حقوق اللہ تعالیٰ کی طرف سے عطا کردہ ہیں اور ان کے ساتھ فرائض اور اخلاقی ذمہ داریاں بھی وابستہ ہیں، جبکہ منشور انسانوں کا بنایا ہوا ہے۔","نتیجہ: اقوامِ متحدہ کے منشور میں دیے گئے اکثر حقوق ہمارے دین اسلام کی تعلیمات کے عین مطابق ہیں، جو اسلامی تعلیمات کی عالمگیریت کا ثبوت ہے۔"]},{"q":[["pak12-ch4-exercise",28]],"s":["آئینی اقدامات: قراردادِ مقاصد (1949ء)، 1956ء، 1962ء اور 1973ء کے آئینوں میں اسلامی دفعات، اسلامی نظریاتی کونسل اور 1985ء میں قراردادِ مقاصد کو آئین کا حصہ بنانا۔","قانونی و عدالتی اصلاحات (1977ء کے بعد): حدود آرڈیننس کے ذریعے زنا، چوری، قذف اور شراب نوشی کی اسلامی سزائیں؛ وفاقی شرعی عدالت اور شریعت بنچ؛ اسلامی یونیورسٹی اور شریعہ فیکلٹی کا قیام۔","معاشی اصلاحات: 20 جون 1980ء کو زکوٰۃ و عشر آرڈیننس؛ جنوری 1981ء سے بلاسود بینکاری (نفع و نقصان میں شراکت)۔","تعلیمی و سماجی اصلاحات: 1979ء کی تعلیمی پالیسی؛ اسلامیات اور مطالعۂ پاکستان لازمی مضامین؛ مسجد مکتب سکیم؛ دینی مدارس کی اسناد کو مساوی درجہ؛ دفاتر میں نمازِ ظہر باجماعت؛ احترامِ رمضان آرڈیننس؛ ریڈیو و ٹی وی پر اذان اور قرآن و عربی کی تعلیم؛ وفاقی محتسب کا تقرر۔","1988ء کے بعد بھی یہ سلسلہ جاری رہا اور مئی 1991ء میں پارلیمنٹ نے شریعت بل منظور کیا۔ ان تمام کوششوں کا مقصد ایک فلاحی، جمہوری اور اسلامی معاشرے کا قیام ہے جو ایک مسلسل اور بتدریج ارتقائی عمل سے ہی ممکن ہے۔"]}]}},"5":{"lang":"ur","items":{"mcqs":[{"q":[["pak12-ch5-exercise-1",8]],"ob":1,"s":["1973ء کے آئین کے مطابق پاکستان ایک وفاقی ریاست ہے جس میں اختیارات مرکز اور صوبوں کے درمیان تقسیم ہیں (نظامِ حکومت پارلیمانی ہے)۔"],"c":3},{"q":[["pak12-ch5-exercise-1",9]],"ob":1,"s":["سینیٹ کی کل نشستیں 104 ہیں جن میں چاروں صوبوں کو برابر نمائندگی دی گئی ہے۔"],"c":3},{"q":[["pak12-ch5-exercise-1",10]],"ob":1,"s":["قومی اسمبلی میں صوبہ خیبر پختونخوا (بشمول نئے ضم شدہ اضلاع) کی کل نشستیں 55 ہیں۔"],"c":2},{"q":[["pak12-ch5-exercise-1",11]],"ob":1,"s":["قومی اسمبلی کے اراکین پانچ سال کے لیے منتخب ہوتے ہیں۔"],"c":2},{"q":[["pak12-ch5-exercise-1",12]],"ob":1,"s":["حضرت عمر فاروقؓ نے سلطنت کو آٹھ انتظامی صوبوں میں تقسیم کیا تھا۔"],"c":3}],"objective":[{"q":[["pak12-ch5-exercise-1",2]],"s":["اسلام","اسلام نے سب سے پہلے فلاحی ریاست کا تصور پیش کیا اور عوام کی فلاح کے لیے عدالتیں، نہریں، کتب خانے اور یتیموں سے بیواؤں تک کے وظائف مقرر کیے۔"],"a":"اسلام"},{"q":[["pak12-ch5-exercise-1",3]],"s":["آٹھ","حضرت عمرؓ نے سلطنت کو آٹھ انتظامی صوبوں میں تقسیم کیا اور صوبوں کو اضلاع میں۔"],"a":"آٹھ"},{"q":[["pak12-ch5-exercise-1",4]],"s":["104","سینیٹ کی کل نشستوں کی تعداد 104 ہے۔"],"a":"104"},{"q":[["pak12-ch5-exercise-1",5]],"s":["قانون","اچھی حکمرانی کی اوّلین شرط قانون کی حکمرانی ہے؛ قانون عملاً سب کے لیے برابر ہونا چاہیے۔"],"a":"قانون"},{"q":[["pak12-ch5-exercise-1",6]],"s":["چار سالہ","2001ء میں قائم ہونے والے نئے مقامی و ضلعی نظام نے 2005ء میں اپنی پہلی مقررہ چار سالہ مدت مکمل کی۔"],"a":"چار سالہ"}],"shortQuestions":[{"q":[["pak12-ch5-exercise-1",14]],"s":["حضرت عمرؓ نے عوامی فلاح کو دوسرے کاموں پر ترجیح دی۔","انہوں نے دنیا کی تاریخ میں پہلی بار ضرورت مندوں کے وظائف مقرر کیے؛ معذوروں اور ناداروں کو بیت المال سے تنخواہیں دی گئیں؛ اکثر شہروں میں مہمان خانے بنوائے جہاں مسافروں کو بیت المال کے خرچ پر کھانا ملتا تھا۔","نہریں کھدوائیں، سڑکیں اور سرائیں بنوائیں، مردم شماری اور زمینوں کی پیمائش کروائی۔"]},{"q":[["pak12-ch5-exercise-1",15]],"s":["حضرت عمرؓ دو طریقوں سے عمال (افسران) مقرر کرتے تھے: (1) مہاجرین و انصار کا اجتماع بلا کر مجلسِ شوریٰ کے اراکین افسر کا انتخاب کرتے؛ (2) مقامی باشندوں کو اپنے افسر خود منتخب کرنے کا حق دیا جاتا۔","تقرر سے پہلے عہد لیا جاتا کہ وہ ترکی گھوڑا استعمال نہیں کریں گے، باریک کپڑا نہیں پہنیں گے، چھنا ہوا آٹا استعمال نہیں کریں گے، دروازے پر دربان نہیں رکھیں گے اور ضرورت مندوں کے لیے دروازے ہر وقت کھلے رکھیں گے۔ حج کے دنوں میں ان کی شکایات سنی جاتیں۔"]},{"q":[["pak12-ch5-exercise-1",16]],"s":["صدر کابینہ کو کسی بھی معاملے پر — خواہ وزیرِاعظم یا کسی وزیر نے فیصلہ کر لیا ہو مگر کابینہ میں زیرِ بحث نہ آیا ہو — دوبارہ غور کرنے کا حکم دے سکتا ہے۔","وہ اپنے فرائض کی انجام دہی کے دوران وزیرِاعظم سے معلومات اور مشورہ طلب کر سکتا ہے، اور اہم تقرریاں (چیف الیکشن کمشنر، اعلیٰ عدالتوں کے جج، سفیر) کرتا ہے؛ وہ سزائیں معاف، کم یا ملتوی بھی کر سکتا ہے۔"]},{"q":[["pak12-ch5-exercise-2",0]],"s":["اچھی حکمرانی کی اسلامی بنیاد: نبی کریم ﷺ کے لائے ہوئے انقلاب نے اچھی حکمرانی کی بنیاد رکھی۔","اس کے اصول: حصولِ علم پر زور؛ عورتوں کو حقوق اور آزادی؛ رنگ و نسل کی بجائے تقویٰ کو معیارِ برتری قرار دینا؛ خلفائے راشدین کے دور میں جمہوریت اور شوریٰ؛ حکمران عوام کے خادم اور بیت المال عوام کی امانت؛ فلاحی ریاست؛ بنیادی حقوق کا تحفظ؛ عدلیہ کی آزادی۔","حضور ﷺ کا ارشاد: \"قوم کا سردار اس کا خادم ہوتا ہے۔\""]},{"q":[["pak12-ch5-exercise-2",1]],"s":["وزیرِاعظم کابینہ کا سربراہ اور صدر کا مشیرِ اعلیٰ ہے؛ پوری حکومتی مشینری اس کے گرد گھومتی ہے اور وہ پورے انتظامیہ کا نگران اور قومی راہنما ہے۔","اختیارات: وزرا کی فہرست تیار کر کے صدر سے منظوری لیتا اور ان کی نگرانی و ہم آہنگی کرتا ہے؛ قومی اسمبلی میں اکثریتی جماعت کا راہنما ہونے کی وجہ سے قائدِ ایوان ہے اور پالیسی کے اہم اعلانات کرتا ہے؛ صدر اور کابینہ کے درمیان رابطے کا ذریعہ ہے اور صدر کو حکومتی امور سے آگاہ رکھتا ہے؛ صدر اس کے مشورے پر قومی اسمبلی تحلیل کر سکتا ہے۔"]},{"q":[["pak12-ch5-exercise-2",2]],"s":["تعلیم کی کمی (شرحِ خواندگی تقریباً 58 فیصد)؛ معیاری منصوبہ بندی کا فقدان؛ سیاسی جماعتوں کی بڑھتی تعداد اور ٹوٹ پھوٹ۔","وفاقی اصولوں سے انحراف؛ مذہبی انتہا پسندی اور فرقہ واریت؛ قانون کی پاسداری نہ ہونا اور پیچیدہ و مہنگا عدالتی نظام۔"]},{"q":[["pak12-ch5-exercise-2",3]],"s":["قانون کی حکمرانی؛ تمام امور میں عوام کی شرکت؛ عہدے اور اختیار کا آئینی و قانونی جواز۔","مسلسل اور بلاامتیاز احتساب؛ مردم شماری کی بنیاد پر منصوبہ بندی؛ شفاف کارکردگی۔","فوری اور سستا انصاف؛ پائیدار معاشی ترقی؛ وفاقی اکائیوں میں وسائل کی منصفانہ تقسیم۔"]}]}},"6":{"lang":"ur","items":{"mcqs":[{"q":[["pak12-ch6-exercise-1",8]],"ob":1,"s":["مشہور چینی سیاح اور زائر ہیون سانگ ساتویں صدی عیسوی کے آغاز میں گندھارا آیا تھا۔"],"c":2},{"q":[["pak12-ch6-exercise-1",9]],"ob":1,"s":["ہندوؤں کی مشہور مذہبی کتاب \"رگ وید\" ہے؛ گندھارا کا ذکر پہلی بار اسی میں ملتا ہے۔"],"c":0},{"q":[["pak12-ch6-exercise-1",10]],"ob":1,"s":["گندھارا ایران کے ہخامنشی بادشاہ دارا (Darius) کی سلطنت کا ایک صوبہ تھا۔"],"c":0},{"q":[["pak12-ch6-exercise-1",11]],"ob":1,"s":["حضرت عمرؓ نے حضرت شفا بنت عبداللہؓ کو پرائس کنٹرول آفیسر (بازار کا محتسب) مقرر کیا تھا۔"],"c":2}],"objective":[{"q":[["pak12-ch6-exercise-1",2]],"s":["گہوارہ","پاکستان کی سرزمین قدیم ثقافتوں اور تہذیبوں کا گہوارہ رہی ہے؛ ان میں وادیٔ سندھ کی تہذیب اور گندھارا تہذیب بہت اہم ہیں۔"],"a":"گہوارہ"},{"q":[["pak12-ch6-exercise-1",3]],"s":["پشکلاوتی (موجودہ چارسدہ)","چھٹی صدی قبل مسیح سے پہلی صدی عیسوی تک گندھارا کا دارالحکومت پشکلاوتی (چارسدہ) تھا۔"],"a":"پشکلاوتی (موجودہ چارسدہ)"},{"q":[["pak12-ch6-exercise-1",4]],"s":["کنشک پورہ","پشکلاوتی کے بعد پشاور گندھارا کا دارالحکومت بنا جسے اس دور میں کنشک پورہ کہا جاتا تھا۔"],"a":"کنشک پورہ"},{"q":[["pak12-ch6-exercise-1",5]],"s":["زبان","ثقافت میں سب سے بنیادی چیز زبان ہے؛ پاکستان کی ثقافتیں (پختون، پنجابی، سندھی، بلوچ وغیرہ) زبان کی بنیاد پر ہی مشہور ہیں۔"],"a":"زبان"},{"q":[["pak12-ch6-exercise-1",6]],"s":["ٹیکسلا","گندھارا کا ثقافتی مرکز ٹیکسلا تھا جو علم و فن کا مرکز تھا اور یہاں بدھ مت کی درس گاہیں مشہور تھیں۔"],"a":"ٹیکسلا"},{"q":[["pak12-ch6-exercise-1",13]],"tf":"tf","s":["درست۔ حضور ﷺ کے زمانے میں خواتین دینی اور دنیاوی دونوں طرح کی تعلیم حاصل کرتی تھیں اور زندگی کے مختلف شعبوں میں سرگرم تھیں۔"],"c":0},{"q":[["pak12-ch6-exercise-1",14]],"tf":"tf","s":["غلط۔ گندھارا کا ثقافتی مرکز ٹیکسلا تھا؛ چارسدہ (پشکلاوتی) اس کا سیاسی دارالحکومت تھا۔"],"c":1},{"q":[["pak12-ch6-exercise-1",15]],"tf":"tf","s":["درست۔ بلوچ ثقافت پر ایرانی ثقافت کے اثرات بہت گہرے ہیں جو ان کی دستکاریوں اور برتنوں میں بھی نظر آتے ہیں۔"],"c":0},{"q":[["pak12-ch6-exercise-1",16]],"tf":"tf","s":["غلط۔ موہنجو دڑو وادیٔ سندھ کی تہذیب کا مرکز تھا جو صوبہ سندھ میں ہے، بلوچ ثقافت کا نہیں۔"],"c":1},{"q":[["pak12-ch6-exercise-1",17]],"tf":"tf","s":["درست۔ گندھارا آرٹ پر ہندوستانی، یونانی، رومی اور ایرانی فن کاروں کا گہرا اثر تھا؛ مجسمہ سازی میں یونانی اثرات نمایاں ہیں۔"],"c":0},{"q":[["pak12-ch6-exercise-2",0]],"d":"pak12-ch6-match","s":["درست جوڑ:","اے اسٹڈی آف ہسٹری — پروفیسر آرنلڈ ٹائن بی۔","ساتویں صدی عیسوی — ہیون سانگ۔","گندھارا — ہخامنشی بادشاہ کی سلطنت کا حصہ۔","ملاکھڑا — سندھ۔","بادشاہی مسجد — لاہور۔"]}],"shortQuestions":[{"q":[["pak12-ch6-exercise-2",2]],"s":["ثقافت زندگی کی مختلف سرگرمیوں کا وہ خاکہ، نمونہ اور طریقہ ہے جس پر معاشرہ عمل کرتا ہے اور جسے ایک نسل سے دوسری نسل کو منتقل کرتا ہے۔","ٹائلر کے مطابق: ثقافت سے مراد علم، عقیدہ، فن، اخلاق، قانون، رسم و رواج اور وہ تمام صلاحیتیں اور عادات ہیں جو انسان معاشرے سے حاصل کرتا ہے۔"]},{"q":[["pak12-ch6-exercise-2",3]],"s":["پختون ثقافت کے بنیادی اجزا: محنت، غیرت، مہمان نوازی، اسلحہ سے محبت، لوک گیت، فتح و محبت کی رومانی داستانیں، نشانہ بازی، گھڑ دوڑ، برداشت، بزرگوں کا احترام، عزت و آزادی کی حفاظت اور سرکشی (کسی کے آگے نہ جھکنا)۔","یہی خصوصیات (پختون ولی) اسے دوسری ثقافتوں سے ممتاز کرتی ہیں۔"]},{"q":[["pak12-ch6-exercise-2",4]],"s":["پنجابی ثقافت میں میلے، تہوار، شادیاں، لڈی ناچ، گھڑ سواری اور دوڑ، بسنت، کھیل تماشے، صوفیا سے محبت، لوک ادب سے لگاؤ، اچھے کھانوں کا شوق اور قصہ گوئی نمایاں ہیں۔","اس ثقافت میں مذاق، محاورے اور قصہ کہانی اپنی پوری دلکشی کے ساتھ موجود ہیں۔"]},{"q":[["pak12-ch6-exercise-2",5]],"s":["سندھی تہذیب کے چند رسم و رواج: کارو کاری کی رسم، لڑکیوں کی قرآن مجید سے شادی، ملاکھڑا (سندھی کشتی)، بیلوں کی دوڑ، کلہاڑی بطور ہتھیار، عورتوں کے لباس پر کشیدہ کاری، مردوں کی سندھی ٹوپی اور اجرک/لنگی، لمبی مونچھیں، مہمان نوازی اور جرگہ نظام۔"]},{"q":[["pak12-ch6-exercise-2",6]],"s":["موہنجو دڑو وادیٔ سندھ کی تہذیب کا اہم ترین مقام ہے جو صوبہ سندھ میں واقع ہے۔","یہ ایک منظم شہری تہذیب تھی: کشادہ گلیاں، صفائی کا بہترین انتظام، گلیوں میں پکی نالیاں، پکی اینٹوں کے مکانات اور فرش، ہوا اور روشنی کا معقول انتظام، تہ خانے، کشادہ غسل خانے اور پینے کے پانی کے کنویں۔ اس سے پتا چلتا ہے کہ یہاں کے لوگ مہذب اور ہنرمند تھے۔"]},{"q":[["pak12-ch6-exercise-2",7]],"s":["بلوچ ثقافت کی خصوصیات: قدیم روایات، سرداری نظام، شادی بیاہ کے خاص رسم و رواج، لباس پر کشیدہ کاری، طرح طرح کے مخصوص بلوچی کھانے (سجی وغیرہ)، بندوق، تلوار اور خانہ بدوشی۔","اس پر ایرانی ثقافت کے گہرے اثرات ہیں اور جدید تعلیم و ذرائع مواصلات سے دوری کی وجہ سے یہ اپنی قدیم اقدار کے ساتھ آج بھی رائج ہے۔"]}],"longQuestions":[{"q":[["pak12-ch6-exercise-2",8]],"s":["پروفیسر آرنلڈ ٹائن بی نے اس خطے (قدیم ہند) کو ابتدائی تہذیبوں کا گہوارہ قرار دیا؛ آثارِ قدیمہ سے بھی ثابت ہوتا ہے کہ مصر اور میسوپوٹیمیا کی طرح یہاں بھی دنیا کی قدیم ترین تہذیبیں پروان چڑھیں۔","وادیٔ سندھ کی تہذیب: موہنجو دڑو اور ہڑپہ اس کے اہم مقامات ہیں؛ یہ شہری تہذیب تھی جس میں منظم شہر، کشادہ گلیاں، پکی نالیاں، پکی اینٹوں کے مکانات اور صفائی کا اعلیٰ انتظام تھا۔","گندھارا تہذیب: پشاور، چارسدہ، سوات اور ٹیکسلا اس کے اہم مقامات؛ پشکلاوتی (چارسدہ) اور کنشک پورہ (پشاور) دارالحکومت؛ ٹیکسلا علمی و ثقافتی مرکز؛ گندھارا آرٹ (بدھ مت کے مجسمے) جس پر یونانی، رومی، ایرانی اور ہندوستانی اثرات تھے۔","علاقائی ثقافتیں: پختون، پنجابی، سندھی، بلوچ، براہوی، سرائیکی، پوٹھوہاری، کشمیری اور گوجری ثقافتیں زبان کی بنیاد پر پہچانی جاتی ہیں۔","اسلامی دور: گزشتہ ایک ہزار سال سے اسلام نے یہاں کی ثقافت پر گہرے اثرات ڈالے — بادشاہی مسجد، شاہی قلعہ، شالامار باغ، مسجد مہابت خان، ٹھٹھہ کی جامع مسجد، مکلی اور چوکنڈی کے مقبرے اسی ورثے کا حصہ ہیں۔"]},{"q":[["pak12-ch6-exercise-2",9]],"s":["پاکستانی ثقافت کی سب سے بڑی خصوصیت اس کا اسلامی رنگ ہے؛ آبادی کی بھاری اکثریت مسلمان ہے اور اسلام رنگ و نسل کے امتیاز کی نفی کر کے سب کو اخوت اور محبت کے رشتے میں باندھ دیتا ہے۔","مخلوط ثقافت: مقامی باشندوں کے ساتھ عرب، ایرانی، تورانی اور یونانی نسلوں کے لوگ یہاں آباد ہوئے؛ سب نے مل کر ایک مشترکہ ثقافت بنائی جس میں علاقائی رنگ ایک دوسرے میں گھل مل گئے ہیں۔","مشترکہ اقدار: سادہ معاشرت، مشترکہ خاندانی نظام، بزرگوں کا احترام، مہمان نوازی، قومی لباس (شلوار قمیص)، مشترکہ کھانے، شادی بیاہ اور غمی خوشی کے اسلامی رنگ والے رسم و رواج۔","قومی زبان اردو، قومی تہوار، کھیل اور میلے (جیسے ہاکی، کرکٹ، قومی دن) تمام علاقوں کے لوگوں کو قریب لاتے ہیں۔","یوں پاکستانی ثقافت علاقائی تنوع کے باوجود قوم کو اتحاد اور یکجہتی کی لڑی میں پروتی ہے؛ \"پاکستانی بنو، پاکستانی خریدو\" کا جذبہ بھی اسی قومی شناخت کو مضبوط کرتا ہے۔"]},{"q":[["pak12-ch6-exercise-2",10]],"s":["اسلام میں جنس کی بنیاد پر مرد اور عورت میں کوئی امتیاز نہیں؛ اللہ تعالیٰ نے دونوں کو حقوق اور ذمہ داریاں عطا کی ہیں، البتہ جسمانی ساخت کے فرق کے مطابق ذمہ داریوں میں فرق رکھا گیا ہے۔","قرآنِ مجید (سورۃ التوبہ): مومن مرد اور مومن عورتیں ایک دوسرے کے دوست ہیں، نیکی کا حکم دیتے اور برائی سے روکتے ہیں، نماز قائم کرتے اور زکوٰۃ دیتے ہیں۔ (آل عمران 3:195): میں کسی مرد یا عورت کی محنت کا اجر ضائع نہیں کروں گا۔","حضور ﷺ کے زمانے میں خواتین دینی اور دنیاوی تعلیم حاصل کرتی تھیں اور مردوں کے شانہ بشانہ سرگرم تھیں؛ امام ابن قیم کی فہرست میں حضرت عائشہؓ، حضرت ام سلمہؓ، حضرت حفصہؓ جیسی کئی خواتین فقیہ شامل ہیں۔","خواتین کو اہم سرکاری عہدے بھی دیے گئے، جیسے حضرت عمرؓ نے حضرت شفا بنت عبداللہؓ کو پرائس کنٹرول آفیسر مقرر کیا۔","اسلام نے عورت کو تعلیم، روزگار، کاروبار، جائیداد کی ملکیت، وراثت اور اپنی رائے کے اظہار کا مکمل حق دیا ہے؛ اس لیے یہ کہنا درست ہے کہ اسلام میں جنس کی بنیاد پر کوئی امتیاز نہیں۔"]},{"q":[["pak12-ch6-exercise-2",11]],"s":["تحریکِ پاکستان میں مسلمان خواتین (محترمہ فاطمہ جناح، بیگم رعنا لیاقت علی خان، بیگم جہاں آرا شاہنواز وغیرہ) نے بھرپور حصہ لیا اور تاریخ پر انمٹ نقوش چھوڑے۔","سیاسی کردار: 2002ء میں آئینی ترمیم کے ذریعے قومی اور صوبائی اسمبلیوں میں خواتین کے لیے نشستیں مخصوص کی گئیں؛ آج خواتین اسمبلیوں، سینیٹ اور مقامی حکومتوں کی رکن، وزیر، سفیر حتیٰ کہ وزیرِاعظم (محترمہ بے نظیر بھٹو) اور اسپیکر کے عہدوں تک پہنچیں۔ خواتین عام نشستوں پر بھی انتخاب لڑ سکتی ہیں۔","معاشی کردار: ہم روزانہ دیکھتے ہیں کہ خواتین ڈاکٹر، انجینئر، پروفیسر، استانیاں، وکیل، سرکاری افسر، بینکار، فیشن ڈیزائنر، کاروباری اور سرمایہ کار کی حیثیت سے ملکی معیشت میں قابلِ قدر خدمات انجام دے رہی ہیں۔","دیہات میں خواتین کھیتی باڑی، مویشی پالنے اور دستکاری (کشیدہ کاری، قالین بافی) کے ذریعے گھریلو آمدنی میں اضافہ کرتی ہیں۔","چونکہ خواتین آبادی کا تقریباً نصف ہیں، اس لیے ان کی شرکت کے بغیر ملک کی ترقی ممکن نہیں؛ ان کی تعلیم، تحفظ اور روزگار کے بہتر مواقع ان کا کردار مزید بڑھا سکتے ہیں۔"]}]}},"7":{"lang":"ur","items":{"mcqs":[{"q":[["pak12-ch7-exercise",7]],"ob":1,"s":["\"اردو\" ترکی زبان کا لفظ ہے جس کے معنی \"لشکر\" کے ہیں۔"],"c":3},{"q":[["pak12-ch7-exercise",8]],"ob":1,"s":["تحقیق سے ثابت ہوا ہے کہ لاہور کے رہنے والے مشہور شاعر خواجہ مسعود سعد سلمان اردو کے پہلے شاعر تھے۔"],"c":2},{"q":[["pak12-ch7-exercise",9]],"ob":1,"s":["عربوں کے دور میں سندھی میں عربی الفاظ اور مغلوں کے دور میں فارسی کے الفاظ کثرت سے داخل ہوئے۔"],"c":2},{"q":[["pak12-ch7-exercise",10]],"ob":1,"s":["تحقیق کے مطابق پشتو کی سب سے قدیم کتاب بایزید انصاری کی لکھی ہوئی \"خیر البیان\" ہے۔"],"c":0},{"q":[["pak12-ch7-exercise",11]],"ob":1,"s":["محمود غزنوی کے دور میں سیف اللہ نامی شخص نے پشتو زبان کے حروفِ تہجی ترتیب دیے جو آج تک رائج ہیں۔"],"c":3}],"objective":[{"q":[["pak12-ch7-exercise",2]],"s":["تقریباً تیس (30)","پاکستان میں اردو کے علاوہ تقریباً تیس مختلف علاقائی زبانیں بولی جاتی ہیں۔"],"a":"تقریباً تیس (30)"},{"q":[["pak12-ch7-exercise",3]],"s":["گورمکھی","پنجابی زبان کا اصل رسم الخط گورمکھی ہے، مگر پاکستان میں یہ اردو/فارسی رسم الخط میں لکھی جاتی ہے۔"],"a":"گورمکھی"},{"q":[["pak12-ch7-exercise",4]],"s":["امیر حمزہ خان شنواری","پشتو شاعری میں غزل کے حوالے سے بڑا نام امیر حمزہ خان شنواری کا ہے جنہیں \"بابائے غزل\" کہا جاتا ہے۔"],"a":"امیر حمزہ خان شنواری"},{"q":[["pak12-ch7-exercise",5]],"s":["سندھی","پوری اسلامی دنیا میں مقامی زبانوں میں سب سے پہلے قرآن مجید کا ترجمہ سندھی زبان میں ہوا۔"],"a":"سندھی"},{"q":[["pak12-ch7-exercise",13]],"tf":"tf","s":["درست۔ شاہجہان کے دور میں دہلی کے جس بازار میں فوجی اور امرا رہتے تھے اسے \"اردوئے معلیٰ\" کا نام دیا گیا، اور وہاں بولی جانے والی زبان بھی اسی نسبت سے اردوئے معلیٰ کہلائی۔"],"c":0},{"q":[["pak12-ch7-exercise",14]],"tf":"tf","s":["غلط۔ دوسری بڑی زبانوں کی طرح اردو ادب کا آغاز بھی شاعری سے ہوا، نثر سے نہیں۔"],"c":1},{"q":[["pak12-ch7-exercise",15]],"tf":"tf","s":["درست۔ امیر حمزہ خان شنواری نے پشتو شاعری میں غزل کو بہت ترقی دی اور باقاعدہ صنف کا درجہ دیا، اسی لیے وہ بابائے غزل کہلاتے ہیں۔"],"c":0},{"q":[["pak12-ch7-exercise",16]],"tf":"tf","s":["درست۔ \"پنجابی\" خود فارسی کا لفظ ہے جو \"پنج\" (پانچ) اور \"آب\" (پانی) سے مل کر بنا ہے۔"],"c":0},{"q":[["pak12-ch7-exercise",17]],"tf":"tf","s":["درست۔ بعض انگریزوں نے پشتو زبان میں کتابیں لکھیں جن میں میجر راورٹی کا نام سرِفہرست ہے۔"],"c":0},{"q":[["pak12-ch7-exercise",18]],"tf":"tf","s":["درست۔ بلوچی پاکستان کے علاوہ ایران اور جنوبی افغانستان میں بولی جاتی ہے، اور اس کے بولنے والے ترکمانستان اور عمان میں بھی موجود ہیں۔"],"c":0},{"q":[["pak12-ch7-exercise",19]],"d":"pak12-ch7-match","s":["درست جوڑ:","وارث شاہ — ہیر رانجھا۔","ہاشم شاہ — سسی پنوں۔","فضل شاہ — سوہنی مہینوال۔","حافظ برخوردار — مرزا صاحباں۔","خوشحال خان خٹک — فضل نامہ۔"]}],"shortQuestions":[{"q":[["pak12-ch7-exercise",21]],"s":["پاکستان جس خطے میں واقع ہے وہاں کئی قدیم تہذیبوں کے آثار ملے ہیں جن میں وادیٔ سندھ کی تہذیب (موہنجو دڑو، ہڑپہ) اور گندھارا تہذیب (ٹیکسلا، پشاور، چارسدہ، سوات) شامل ہیں۔"]},{"q":[["pak12-ch7-exercise",22]],"s":["اردو پاکستان کے چاروں صوبوں کے لوگوں کے درمیان رابطے کا اہم ذریعہ ہے؛ ملک کے تمام علاقوں کے لوگ، خصوصاً پڑھا لکھا طبقہ، اردو بولتا اور سمجھتا ہے۔","چونکہ اردو کسی بھی صوبے کے لوگوں کی مادری زبان نہیں، اس لیے اس کی قومی زبان کی حیثیت غیر متنازعہ اور سب کے لیے قابلِ قبول ہے؛ یہ تحریکِ پاکستان کی زبان بھی رہی اور اسلامی تہذیب کی ترجمان ہے۔"]},{"q":[["pak12-ch7-exercise",23]],"s":["مختلف ادوار میں اردو کو ہندوی، ہندی، ہندوستانی، ریختہ، اردوئے معلیٰ، زبانِ دہلوی کہا گیا؛ دکن اور گجرات پہنچ کر اسے دکنی اور گجراتی بھی کہا گیا۔"]},{"q":[["pak12-ch7-exercise",24]],"s":["پشتو اکیڈمی کی بنیاد 1955ء میں پشاور یونیورسٹی میں رکھی گئی۔","مقصد: پشتو میں علمی و ادبی کتابوں کی کمی دور کرنا؛ پشتو ادب سے متعلق کتابیں جمع اور محفوظ کرنا؛ دوسری زبانوں کی مستند کتابوں کے پشتو تراجم کرنا؛ نایاب پشتو کتابیں تلاش، مرتب اور شائع کرنا اور مختلف موضوعات پر پشتو میں کتابیں لکھوانا۔"]}],"longQuestions":[{"q":[["pak12-ch7-exercise",25]],"s":["\"پنجابی\" فارسی کا لفظ ہے (پنج + آب)؛ پنجاب پانچ دریاؤں کی سرزمین ہے۔ اس کا اصل رسم الخط گورمکھی ہے مگر پاکستان میں اردو/فارسی رسم الخط میں لکھی جاتی ہے۔ یہ پنجاب کے علاوہ کئی دوسرے علاقوں میں بھی بولی جاتی ہے۔","ادب کا آغاز: پنجابی ادب کا آغاز بابا فرید گنج شکرؒ کی صوفیانہ شاعری سے ہوا؛ مادھو لال حسین، سلطان باہو، بلھے شاہ اور وارث شاہ اس کے بڑے شاعر ہیں جن کی شاعری کا محور تصوف اور عشق ہے۔","داستان گوئی: وارث شاہ کی \"ہیر رانجھا\"، ہاشم شاہ کی \"سسی پنوں\"، فضل شاہ کی \"سوہنی مہینوال\" اور حافظ برخوردار کی \"مرزا صاحباں\" مشہور منظوم داستانیں ہیں جو اس زمانے کی تاریخی، مذہبی اور سماجی زندگی کی عکاس ہیں۔","لوک شاعری اور گیت: ڈھولا، ماہیا، دوہڑا، ٹپے، بولیاں، دھمال، جھومر، بھنگڑا اور لڈی۔","نثر: باقاعدہ نثر نگاری بیسویں صدی میں شروع ہوئی؛ اس سے پہلے نثر صرف مذہبی موضوعات تک محدود تھی؛ بعد میں ڈرامہ، تذکرہ نگاری، افسانہ اور تحقیق میں قابلِ قدر کام ہوا۔"]},{"q":[["pak12-ch7-exercise",26]],"s":["اہمیت: اردو پاکستان کی قومی زبان ہے اور چاروں صوبوں کے درمیان رابطے کا مؤثر ذریعہ؛ یہ ہند آریائی خاندان کی زبان ہے جو مسلمانوں کے دور میں عرب، ایرانی، ترک، افغان اور ہندوستانی لشکریوں کے میل جول سے وجود میں آئی۔","یہ سرکاری کاموں، تعلیم، صحافت، ریڈیو، ٹیلی وژن اور ادب کی زبان ہے؛ اس کا دامن عربی، فارسی، ترکی اور علاقائی زبانوں کے الفاظ سے مالامال ہے۔","قومی یکجہتی میں کردار: اردو کسی صوبے کی مادری زبان نہیں، اس لیے سب کے لیے غیر متنازعہ ہے؛ ملک کے ہر حصے کا شخص اسے بولتا اور سمجھتا ہے، یوں یہ مختلف زبانیں بولنے والوں کو ایک لڑی میں پروتی ہے۔","تحریکِ پاکستان میں اردو مسلمانوں کی شناخت اور اتحاد کی علامت بنی؛ قائدِاعظم نے اسے قومی زبان قرار دیا۔","اردو ادب (اقبال، حالی وغیرہ) نے اسلامی اقدار اور قومی جذبے کو فروغ دیا؛ اس طرح اردو قومی وحدت، ثقافتی ہم آہنگی اور قومی شعور کی ضامن ہے۔"]},{"q":[["pak12-ch7-exercise",27]],"s":["پشتو خیبر پختونخوا کے علاوہ بلوچستان، کراچی اور جہاں بھی پختون آباد ہیں بولی اور سمجھی جاتی ہے؛ اس کے دو بنیادی لہجے ہیں: شمال مشرق کا سخت لہجہ اور جنوب مغرب کا نرم لہجہ۔ یہ آریائی زبانوں کی مشرقی ایرانی شاخ سے ہے۔","آغاز: تحریری ادب کا آغاز اسلامی دور سے ہوا؛ محمود غزنوی کے دور میں سیف اللہ نے حروفِ تہجی ترتیب دیے؛ امیر کروڑ پہلا شاعر مانا جاتا ہے؛ قدیم ترین کتاب بایزید انصاری کی \"خیر البیان\" ہے؛ محمد ہوتک کی \"پٹہ خزانہ\" بھی اہم ہے۔","عروج: اٹھارویں صدی میں خوشحال خان خٹک (باز نامہ، دستار نامہ، فضل نامہ — عشق، تصوف، آزادی اور بہادری) اور رحمان بابا (عشقِ حقیقی، تصوف، وعظ و نصیحت) نے پشتو کو بلند مقام دیا۔","انگریزی دور: انگریزوں نے پشتو سیکھی اور اس کی خدمت کی؛ میجر راورٹی نے پشتو میں کتابیں لکھیں؛ 1930ء کی دہائی میں پنجاب یونیورسٹی نے پشتو کے امتحانات شروع کیے اور 1937ء میں پرائمری نصاب میں شامل ہوئی؛ 1955ء میں پشتو اکیڈمی قائم ہوئی۔","جدید دور: لوک گیت (چاربیتہ، ٹپہ، نیمکئی)؛ امیر حمزہ شنواری (بابائے غزل)، سمندر خان سمندر، قلندر مومند، غنی خان، رحمت شاہ سائل، پریشان خٹک وغیرہ؛ بیسویں صدی میں نثر، لغت نویسی اور گرامر میں نمایاں کام ہوا۔"]},{"q":[["pak12-ch7-exercise",28]],"s":["سندھی پاکستان کی قدیم ترین زبان ہے؛ موہنجو دڑو کے قدیم باشندوں کی زبان میں موجودہ سندھی کے کچھ عناصر پائے جاتے ہیں۔","اس پر دراوڑی، سنسکرت، یونانی، ایرانی اور دوسری قدیم زبانوں اور ثقافتوں کے اثرات نمایاں ہیں؛ عربوں کے بعد عربی اور مغلوں کے دور میں فارسی کے الفاظ شامل ہوئے، مگر اس کا لہجہ آج بھی بنیادی طور پر وہی ہے جو بارہویں صدی عیسوی میں تھا۔","اس کا اپنا رسم الخط پراکرت اور سنسکرت کے خاندان سے ہے؛ انگریزوں کے قبضے تک یہ دیوناگری میں لکھی جاتی تھی، پھر عربی و فارسی رسم الخط رائج ہوا۔","پوری اسلامی دنیا میں مقامی زبانوں میں سب سے پہلے قرآن مجید کا ترجمہ سندھی میں ہوا؛ گیارہویں سے چودہویں صدی تک اس کا ابتدائی اسلامی ادبی دور ہے (داستان، قصہ، گنان، بیت، سورٹھ، گاتھا، دوہڑا)۔","اٹھارویں صدی تک شاہ عبداللطیف بھٹائی اور سچل سرمست جیسے عظیم شعرا نے اسے مالامال کر دیا۔ یہ تمام دلائل ثابت کرتے ہیں کہ سندھی ایک قدیم اور ترقی یافتہ زبان ہے۔"]},{"q":[["pak12-ch7-exercise",29]],"s":["بلوچی پاکستان کی اہم علاقائی زبان ہے جو بلوچستان کے وسیع علاقوں کے علاوہ سندھ اور جنوب مغربی پنجاب میں بولی جاتی ہے، اور ایران، جنوبی افغانستان، ترکمانستان اور عمان میں بھی اس کے بولنے والے موجود ہیں؛ یوں یہ پاکستان کو ہمسایہ ممالک سے جوڑتی ہے۔","یہ پشتو کی طرح آریائی زبانوں کی مشرقی ایرانی شاخ سے ہے؛ اس کے دو بڑے لہجے سلیمانی اور مکرانی ہیں؛ موجودہ رسم الخط بنیادی طور پر عربی ہے۔","قدیم بلوچی ادب زبانی روایت سے نسل در نسل منتقل ہوتا رہا؛ 1940ء تک کوئی اخبار یا کتاب شائع نہ ہوئی، مگر قیامِ پاکستان کے بعد بلوچی ادب نے خاصی ترقی کی۔","شاعری اس کا اہم ترین حصہ ہے: رزمیہ شاعری (جرأت، غیرت، برداشت اور بہادری)، رومانی شاعری (محبت) اور لوک کہانیاں (لوری، موتک)؛ انگریزی دور کی شاعری میں تصوف، اخلاق اور انگریزوں سے نفرت؛ مست توکلی اس دور کے بلند پایہ شاعر ہیں۔","25 دسمبر 1949ء سے ریڈیو پاکستان کراچی سے بلوچی پروگرام نشر ہونے لگے؛ آج ریڈیو اور ٹیلی وژن اس کی ترویج میں اہم کردار ادا کر رہے ہیں۔ یہ بلوچ ثقافت، تاریخ اور اقدار کی امین ہے۔"]}]}},"8":{"lang":"ur","items":{"mcqs":[{"q":[["pak12-ch8-exercise",2]],"inline":1,"s":["پاکستان میں بدقسمتی سے تقریباً پہلے نو سال تک کوئی آئین نہ بن سکا (پہلا آئین 1956ء میں نافذ ہوا)، جس سے سیاسی انتشار بڑھتا رہا۔"],"c":1},{"q":[["pak12-ch8-exercise",3]],"inline":1,"s":["1956ء کا آئین صرف ڈھائی سال چل سکا اور 1958ء میں منسوخ کر دیا گیا۔"],"c":1},{"q":[["pak12-ch8-exercise",4]],"inline":1,"s":["اختلافِ رائے جمہوریت کی جان ہے؛ البتہ قومی سلامتی اور یکجہتی کا تقاضا ہے کہ اظہارِ رائے کا حق برداشت اور ذمہ داری سے استعمال کیا جائے۔"],"c":1}],"longQuestions":[{"q":[["pak12-ch8-exercise",6]],"s":["جمہوری ممالک میں سیاسی جماعتیں قومی یکجہتی پیدا کرنے میں بڑا کردار ادا کر سکتی ہیں، جیسے امریکہ اور برطانیہ میں دو ملک گیر جماعتیں پورے ملک کی نمائندگی کرتی ہیں۔","پاکستان میں جماعتوں کی تعداد زیادہ ہے اور اکثر جماعتیں علاقائی، لسانی یا فرقہ وارانہ بنیادوں پر قائم ہیں؛ وہ اقتدار کی رسہ کشی میں الجھ جاتی ہیں جس سے قومی ترقی اور یکجہتی کو نقصان پہنچتا ہے۔","اگر جماعتیں ذاتی اور جماعتی مفادات سے بالاتر ہو کر قومی مسائل پر اصولی مؤقف اپنائیں، ملک گیر پروگرام دیں اور جمہوری روایات کا احترام کریں تو وہ قوم کو متحد کرنے میں مؤثر کردار ادا کر سکتی ہیں۔"]},{"q":[["pak12-ch8-exercise",7]],"s":["قانون کی حکمرانی (بالادستی) کا مطلب ہے کہ قانون کی نظر میں ملک کے تمام لوگ برابر ہوں اور سب کے ساتھ بلا امتیاز انصاف کیا جائے۔","پاکستان میں بدقسمتی سے عملاً اس پر اتنا کام نہیں ہوا؛ طاقتور اور کمزور کے لیے قانون کا اطلاق یکساں نہیں، جس سے احساسِ محرومی پیدا ہوتا ہے۔","قومی یکجہتی کے لیے ضروری ہے کہ قانون امیر و غریب، حاکم و محکوم سب پر یکساں نافذ ہو، عدلیہ آزاد ہو اور انصاف فوری و سستا ہو؛ اچھی حکمرانی کی اوّلین شرط یہی ہے۔"]},{"q":[["pak12-ch8-exercise",8]],"s":["اسلام میں حاکمیت کا تصور دوسرے نظریات سے مختلف ہے: حاکمیتِ اعلیٰ کا سرچشمہ صرف اللہ تعالیٰ کی ذات ہے؛ اسلامی ریاست میں اللہ تعالیٰ ہی حاکمِ اعلیٰ ہے۔","عوام اور ان کے منتخب نمائندے یہ اختیار ایک مقدس امانت کے طور پر قرآن و سنت کی مقرر کردہ حدود کے اندر استعمال کرتے ہیں؛ کوئی ایسا قانون نہیں بنایا جا سکتا جو قرآن و سنت کے منافی ہو۔","یہی تصور قراردادِ مقاصد اور پاکستان کے آئین کی بنیاد ہے۔"]},{"q":[["pak12-ch8-exercise",9]],"s":["آزادی کے بعد پاکستان کو فلاحی ریاست بنانا مقصود تھا، مگر مخصوص مفادات رکھنے والے طبقوں نے معاشی انصاف کا خواب چکنا چور کر دیا؛ دولت کی غیر منصفانہ تقسیم سے عام لوگ محرومیوں کا شکار ہوئے۔","جب لوگ محسوس کرتے ہیں کہ انہیں معاشی انصاف نہیں مل رہا تو ان میں بددلی اور احساسِ محرومی پیدا ہوتا ہے اور یکجہتی کمزور پڑتی ہے۔","ضرورت ہے کہ دولت کی تقسیم منصفانہ ہو، ہر فرد اور خاندان کو اس کا جائز حق ملے، بے روزگاری ختم ہو، ضرورت مندوں اور معذوروں کی کفالت ہو اور صوبوں میں وسائل کی منصفانہ تقسیم ہو؛ اسی سے قومی یکجہتی مضبوط ہوگی۔"]},{"q":[["pak12-ch8-exercise",10]],"s":["قومی یکجہتی کا مطلب: ہر قوم مختلف چھوٹے بڑے گروہوں پر مشتمل ہوتی ہے جن کے معاشی، سماجی اور سیاسی مفادات یکساں نہیں ہوتے؛ جب مختلف صوبوں، مذاہب، طبقوں، ثقافتوں اور نسلوں کے افراد قومی جذبے سے سرشار ہو کر قومی مفاد کو ذاتی و گروہی مفاد پر ترجیح دیں تو اسے قومی یکجہتی کہتے ہیں۔","اسے فروغ دینے والے عناصر: (1) مشترکہ دین اسلام اور نظریۂ پاکستان؛ (2) جدید تعلیم کا فروغ؛ (3) منصفانہ معاشی نظام اور وسائل کی منصفانہ تقسیم؛ (4) دیانت دار اور مؤثر انتظامی مشینری۔","(5) صوبائیت کے خاتمے کی کوشش — ایک صوبے کے شہریوں کو دوسرے صوبوں میں کاروبار، روزگار اور تعلیم کے مواقع؛ (6) سیاست دانوں کا مثبت کردار؛ (7) رواداری اور برداشت؛ (8) ملک و قوم سے وفاداری؛ (9) دوسروں کے حقوق کا احترام اور میرٹ۔","(10) بہتر ذرائع آمد و رفت، قومی زبان اردو اور ذرائع ابلاغ کا مثبت کردار بھی قوم کو قریب لاتے ہیں۔ جذبۂ ایثار، تعاون اور برداشت قومی یکجہتی کی بنیاد ہیں۔"]},{"q":[["pak12-ch8-exercise",11]],"s":["اسلامی جمہوری ریاست میں اسلام کے سنہری اصول اور جمہوریت کے اعلیٰ مقاصد یکجا ہو جاتے ہیں۔","(1) بین الاقوامی امن و سلامتی: اسلام امن و صلح کا دین ہے؛ ایسی ریاست اپنے ملک کے علاوہ دنیا بھر میں امن کی فضا چاہتی ہے۔ (2) عوام کی فلاح: جہالت، غربت اور ناداری کے خلاف مسلسل جدوجہد۔","(3) حاکمیت: اللہ تعالیٰ حاکمِ اعلیٰ اور عوام کے نمائندے امین۔ (4) مثالی حکومت: حاکم و محکوم کا فرق مٹ جاتا ہے اور ہر طبقے کے حقوق محفوظ ہوتے ہیں۔","(5) معاشی و سماجی تحفظ: سب کو یکساں بنیادی سہولیات اور سماجی انصاف۔ (6) غیر مسلم اقلیتوں کا تحفظ: انہیں آئین کے تحت مسلمانوں کے برابر حقوق۔ (7) تعلیم و صحت: ہر فرد کو بلا امتیاز جدید علم اور صحت کی سہولیات۔","اس لیے اسلامی جمہوری ریاست ایک فلاحی، منصفانہ اور پُرامن معاشرے کی ضمانت ہے۔"]},{"q":[["pak12-ch8-exercise",12]],"s":["(1) جمہوری اداروں کی کمزوری — انہیں تسلسل سے کام کرنے کا موقع نہ ملا۔ (2) آئین کا احترام نہ کرنا — پہلے نو سال آئین نہ بنا، 1956ء کا آئین ڈھائی سال چلا، 1973ء کا آئین ترامیم کا شکار رہا۔","(3) درست ترجیحات کا تعین نہ ہونا — لوگ مذہبی، جماعتی، طبقاتی اور علاقائی مفادات کو قومی مفاد پر ترجیح دیتے ہیں۔ (4) خود غرضی اور بدعنوانی۔","(5) غیر منصفانہ معاشی نظام اور دولت کی غیر مساوی تقسیم۔ (6) فرقہ واریت اور عسکریت پسندی۔ (7) سیاسی جماعتوں کی اقتدار کی رسہ کشی اور علاقائی سیاست۔","(8) قانون کی حکمرانی کا فقدان۔ (9) ذرائع آمد و رفت کی کمی (ماضی میں مشرقی و مغربی پاکستان کی دوری)۔ (10) ذرائع ابلاغ کا غیر ذمہ دارانہ کردار، صوبائیت اور لسانی تعصبات۔","میری رائے میں سب سے بڑی رکاوٹیں ناانصافی (معاشی و قانونی)، تعلیم کی کمی اور صوبائی و فرقہ وارانہ تعصبات ہیں؛ ان کا خاتمہ ہی قومی یکجہتی کی کنجی ہے۔"]},{"q":[["pak12-ch8-exercise",13]],"s":["تعلیم حاصل کرنا اور دوسروں کو تعلیم کی طرف راغب کرنا، کیونکہ جہالت تعصبات کی جڑ ہے۔","صوبائی، لسانی، نسلی اور فرقہ وارانہ تعصبات سے بچنا اور ہر پاکستانی کو بھائی سمجھنا — ہم سب پہلے پاکستانی ہیں۔","قانون کا احترام، ٹیکس کی ادائیگی، ووٹ کا درست استعمال (دیانت دار امیدواروں کو ووٹ دینا) اور بدعنوانی سے اجتناب۔","رواداری اور برداشت: اختلافِ رائے کا احترام، دوسروں کے حقوق کا خیال اور میرٹ کی پاسداری۔","ملک و قوم سے وفاداری، قومی مفاد کو ذاتی مفاد پر ترجیح، سماجی خدمت، محنت، اور \"پاکستانی بنو، پاکستانی خریدو\" پر عمل؛ یوں ہم میں سے ہر شخص قومی یکجہتی میں اپنا کردار ادا کر سکتا ہے۔"]}]}},"9":{"lang":"ur","items":{"mcqs":[{"q":[["pak12-ch9-exercise",2]],"ob":1,"n":"کتاب میں یہ اعداد 2002–03ء کے سال کے لیے دیے گئے ہیں جبکہ سوال میں 2003–2004ء لکھا ہے؛ جواب 24 فیصد ہی ہے۔","s":["سبق کے مطابق خام ملکی پیداوار (GDP) کا 24 فیصد زراعت سے حاصل ہوا۔"],"c":2},{"q":[["pak12-ch9-exercise",3]],"ob":1,"s":["اس وقت صنعتوں کی پیداوار کا 60 فیصد زراعت پر مشتمل ہے، کیونکہ زراعت بہت سی صنعتوں کو خام مال فراہم کرتی ہے۔"],"c":2},{"q":[["pak12-ch9-exercise",4]],"ob":1,"s":["ہمارے ہاں پودوں کی بیماریوں کی وجہ سے 25 فیصد زرعی فصلیں ضائع ہو جاتی ہیں۔"],"c":3},{"q":[["pak12-ch9-exercise",5]],"ob":1,"s":["1972ء میں حکومت نے بہت سی صنعتیں اور 1974ء میں تمام نجی تجارتی بینک قومی ملکیت میں لے لیے۔"],"c":2},{"q":[["pak12-ch9-exercise",6]],"ob":1,"s":["ماہرینِ معاشیات کی رائے میں ہر ملک کے کم از کم ایک چوتھائی (25 فیصد) رقبے پر جنگلات ہونے چاہییں۔"],"c":0},{"q":[["pak12-ch9-exercise",7]],"ob":1,"s":["پاکستان میں جامع معاشی منصوبہ بندی کا آغاز 1955ء میں پہلے پنج سالہ منصوبے (1955ء–1960ء) سے ہوا۔"],"c":1}],"objective":[{"q":[["pak12-ch9-exercise",9]],"s":["زرعی","پاکستان ایک ترقی پذیر زرعی ملک ہے؛ زراعت ہماری معیشت میں ریڑھ کی ہڈی کی حیثیت رکھتی ہے۔"],"a":"زرعی"},{"q":[["pak12-ch9-exercise",10]],"s":["67","پاکستان میں 67 فیصد کاشت مصنوعی آبپاشی (نہروں اور ٹیوب ویلوں) سے ہوتی ہے اور باقی بارانی ہے۔"],"a":"67"},{"q":[["pak12-ch9-exercise",11]],"s":["1955ء","پاکستان میں پہلی بار جامع معاشی منصوبہ بندی 1955ء میں شروع ہوئی۔"],"a":"1955ء"},{"q":[["pak12-ch9-exercise",12]],"s":["تین (3)","قیامِ پاکستان کے وقت ملک میں صرف تین میڈیکل کالج تھے۔"],"a":"تین (3)"}],"shortQuestions":[{"q":[["pak12-ch9-exercise",14]],"s":["معاشی منصوبہ بندی اس لیے کی جاتی ہے کہ محدود قومی وسائل کو بہتر طریقے سے استعمال کر کے قومی معیشت اور عوام کی خوشحالی حاصل کی جائے۔","پاکستان میں اس کی ضرورت: نجی شعبے کی کمزوریاں دور کرنا، سرمائے کی کمی پوری کرنا، دولت کی تقسیم میں اصلاح، فضول خرچی پر قابو، بے روزگاری میں کمی، غیر ملکی قرضوں اور سرمایہ کاری کا درست تعین، اور قومی و فی کس آمدنی میں اضافہ اور خوراک میں خود کفالت جیسے مقاصد کا حصول۔"]},{"q":[["pak12-ch9-exercise",15]],"s":["قومی تعلیمی پالیسی (1998–2010ء) کے پانچ اہم بنیادی مقاصد:","1۔ ناخواندگی کے خلاف جہاد۔ 2۔ اکیسویں صدی کی ضروریات کے مطابق نصاب کی تبدیلی۔ 3۔ سکولوں میں کمپیوٹر کی تعلیم اور فنی تعلیم پر زور۔ 4۔ دیہی و شہری اور طالبات و طلبہ کے تعلیمی اداروں کے فرق میں کمی۔ 5۔ ہر سطح پر تعلیم کی سہولیات کی فراہمی (نیز نجی شعبے کی حوصلہ افزائی اور اعلیٰ تعلیم کو بین الاقوامی معیار تک لانا)۔"]},{"q":[["pak12-ch9-exercise",16]],"s":["جنگلات سے ایندھن اور عمارتی لکڑی حاصل ہوتی ہے اور بہت سی صنعتوں کو خام مال ملتا ہے۔","درخت آب و ہوا کو معتدل بناتے ہیں، جانوروں کے لیے بہترین چراگاہیں اور جنگلی حیات کی افزائش کا ذریعہ ہیں، طوفانوں کا زور توڑتے ہیں اور زمین کی زرخیزی کا باعث بنتے ہیں۔"]},{"q":[["pak12-ch9-exercise",17]],"s":["پاکستان کی اہم برآمدات: سوتی دھاگا، سوتی کپڑا، بنا ہوا کپڑا، سلے سلائے کپڑے، بیڈ شیٹس اور دیگر ٹیکسٹائل، چاول، چمڑے کی مصنوعات، قالین، کھیلوں کا سامان، پٹرولیم مصنوعات، جراحی کے آلات، مچھلی اور مچھلی کا تیل۔","یہ اشیا امریکہ، یورپ، جاپان، ہانگ کانگ، دبئی، سعودی عرب اور ایشیا و افریقہ کے دوسرے ممالک کو برآمد کی جاتی ہیں۔"]}],"longQuestions":[{"q":[["pak12-ch9-exercise",18]],"s":["پاکستان میں جامع منصوبہ بندی 1955ء میں شروع ہوئی۔ پہلا پنج سالہ منصوبہ (1955–60ء): قومی آمدنی میں 15 فیصد اضافہ، 20 لاکھ افراد کو روزگار وغیرہ اہداف تھے، مگر عمل درآمد 1957ء میں شروع ہوا؛ قومی آمدنی صرف 11 فیصد اور فی کس آمدنی 3 فیصد بڑھی، اس لیے یہ زیادہ تر شعبوں میں ناکام رہا، البتہ کاغذ، کھاد اور کیمیکل کی صنعتیں قائم ہوئیں۔","دوسرا منصوبہ (1960–65ء): کامیاب ترین رہا — قومی آمدنی 30 فیصد سے زیادہ بڑھی، برآمدات 7 فیصد سالانہ، صنعتی شعبہ 40 فیصد اور زراعت 15 فیصد سے زیادہ بڑھی؛ البتہ روزگار کے مواقع توقع کے مطابق نہ بڑھے۔","تیسرا منصوبہ (1965–70ء): 1965ء کی جنگ اور مشکل حالات کی وجہ سے اکثر اہداف پورے نہ ہوئے — زراعت 4.5 فیصد، صنعت 9 فیصد (ہدف 13 فیصد)، برآمدات 7 فیصد۔","چوتھا منصوبہ (1970–75ء) پاک بھارت جنگ اور نامساعد حالات کی وجہ سے منسوخ کرنا پڑا؛ 1971–78ء تک صرف سالانہ منصوبے بنے۔ پانچواں منصوبہ (1978–83ء) قومی پیداوار میں 7.2 فیصد سالانہ اضافے، زراعت، صنعت، توانائی اور دیہی ترقی کے اہداف کے ساتھ شروع ہوا۔","جائزہ: منصوبہ بندی سے صنعت و زراعت میں ترقی ہوئی مگر سیاسی عدم استحکام، جنگوں، غیر ملکی امداد پر انحصار، تیزی سے بڑھتی آبادی اور ناقص عمل درآمد کی وجہ سے اکثر اہداف پوری طرح حاصل نہ ہو سکے۔"]},{"q":[["pak12-ch9-exercise",19]],"s":["جدید زرعی آلات (ٹریکٹر، تھریشر، کمبائن ہارویسٹر، ٹیوب ویل) کے استعمال کی حوصلہ افزائی۔","کیمیائی کھاد کا بڑھتا استعمال (1952–53ء میں ایک ہزار ٹن سے 2002–03ء میں 24 لاکھ ٹن) اور اچھے بیج کی فراہمی کے لیے سرکاری ادارے۔","پودوں کا تحفظ: محکمۂ تحفظِ نباتات کے ذریعے زمینی اور فضائی سپرے۔ زرعی قرضے: زرعی ترقیاتی بینک کے ذریعے آسان شرائط پر قرضے۔","بہتر آبپاشی: نہروں کی پختگی اور پانی کے ضیاع کی روک تھام؛ زرعی پیداوار کی براہِ راست خریداری کے ادارے؛ قابلِ کاشت بیکار رقبے (40 فیصد) کو کاشت کے قابل بنانا؛ امدادی قیمت کی پالیسی۔","زرعی تعلیم و توسیع: پشاور، فیصل آباد، راولپنڈی، لاہور، کراچی اور کوئٹہ میں زرعی یونیورسٹیاں جو تحقیق بھی کرتی ہیں۔"]},{"q":[["pak12-ch9-exercise",20]],"s":["صنعتی پسماندگی کی وجوہات: (1) تیل، اعلیٰ کوئلے اور خام لوہے جیسی معدنیات کی کمی؛ (2) مشینری کی درآمد کے لیے زرِمبادلہ کی کمی؛ (3) تربیت یافتہ عملے کی کمی؛ (4) سرمائے اور قرض دینے والے اداروں کی کمی؛ (5) پسماندہ ذرائع آمد و رفت۔","(6) سیاسی و سماجی عدم استحکام؛ (7) 1972ء میں صنعتوں اور 1974ء میں بینکوں کو قومیانے سے سرمایہ کاروں کی حوصلہ شکنی؛ (8) سرکاری محکموں میں بدعنوانی اور زیادہ ٹیکس؛ (9) روپے کی قدر میں مسلسل کمی سے درآمدی خام مال اور مشینری کا مہنگا ہونا۔","صنعتی پیداوار بڑھانے کے اقدامات: ذرائع آمد و رفت کا بہتر استعمال؛ زراعت کی ترقی؛ قدرتی وسائل کا اچھا استعمال؛ غیر ملکی منڈیوں تک مال پہنچانے کی صلاحیت؛ بینکاری کا فروغ؛ ٹیکنالوجی کی کمی دور کرنا۔","سستی توانائی؛ قومی حالات میں استحکام؛ آبادی پر کنٹرول؛ ادائیگیوں کے توازن کی درستی؛ ہنرمند افرادی قوت میں اضافہ؛ حکومتی پالیسیوں میں تسلسل؛ تعلیم کا معیار بہتر بنانا۔"]},{"q":[["pak12-ch9-exercise",21]],"s":["برآمدات کی اہمیت: ان سے زرِمبادلہ حاصل ہوتا ہے اور معیشت کے فروغ کے لیے ضروری اشیا درآمد کی جا سکتی ہیں؛ صنعتی ترقی کے ساتھ ہماری برآمدات کی نوعیت خام مال سے تیار مال کی طرف بدلی ہے۔","اہم برآمدات: سوتی دھاگا، سوتی و بنا ہوا کپڑا، سلے سلائے کپڑے، بیڈ شیٹس، ٹیکسٹائل، چاول، چمڑے کی مصنوعات، قالین، کھیلوں کا سامان، پٹرولیم مصنوعات، جراحی کے آلات، مچھلی اور مچھلی کا تیل؛ یہ امریکہ، یورپ، جاپان، ہانگ کانگ، دبئی، سعودی عرب اور ایشیا و افریقہ کو جاتی ہیں۔","اہم درآمدات: مشینری، نقل و حمل کا سامان، کھادیں، کیمیکلز، رنگ، ادویات، لوہا اور لوہے کا سامان، صنعتی خام مال، چائے، اسٹیشنری، خوردنی تیل، پٹرولیم اور دفاعی سامان۔","مسئلہ: ہماری درآمدات برآمدات سے زیادہ ہیں جس سے تجارتی خسارہ اور ادائیگیوں کا عدم توازن پیدا ہوتا ہے؛ حل یہ ہے کہ برآمدات میں تنوع، معیار اور ویلیو ایڈیشن بڑھائی جائے اور غیر ضروری درآمدات کم کی جائیں۔"]},{"q":[["pak12-ch9-exercise",22]],"s":["قدرتی وسائل وہ تمام وسائل ہیں جو قدرت نے عطا کیے ہیں اور دولت کی پیداوار میں مدد دیتے ہیں؛ کسی ملک کی معاشی خوشحالی میں ان کا نمایاں کردار ہے۔","مٹی: پاکستان کی معیشت زراعت پر اور زراعت مٹی کی نوعیت پر منحصر ہے؛ یہاں چکنی، پتھریلی، ریتلی، دلدلی اور میدانی (زرخیز) ہر قسم کی مٹی موجود ہے۔ پانی: دریا اور نہری نظام زراعت اور پن بجلی کی بنیاد ہیں۔","جنگلات: ایندھن، عمارتی لکڑی، صنعتی خام مال، چراگاہیں اور آب و ہوا کی بہتری؛ مگر پاکستان میں جنگلات کی شدید کمی ہے۔","معدنیات: خام لوہا، کرومائٹ، تانبا، نمک، چونے کا پتھر، جپسم، سنگِ مرمر، چینی مٹی، کوئلہ، قدرتی گیس اور خام تیل صنعت و زراعت کی ترقی کی بنیاد ہیں۔","تحفظ: آبادی میں اضافے، پانی کے ضیاع اور آلودگی، جنگلات کی بے دریغ کٹائی اور کیڑے مار ادویات سے وسائل ضائع ہو رہے ہیں؛ ان کا تحفظ اور دانشمندانہ استعمال پائیدار معاشی ترقی کے لیے ضروری ہے۔"]},{"q":[["pak12-ch9-exercise",23]],"s":["بنیادی مقاصد: ناخواندگی کے خلاف جہاد؛ اکیسویں صدی کی ضرورت کے مطابق نصاب؛ کمپیوٹر اور فنی تعلیم؛ دیہی و شہری اور مرد و خواتین اداروں کا فرق کم کرنا؛ ہر سطح پر سہولیات؛ نجی شعبے کی حوصلہ افزائی؛ اعلیٰ تعلیم کو بین الاقوامی معیار تک لانا؛ تحقیق؛ مستحق طلبہ کی مالی مدد؛ شفاف امتحانات؛ بہتر کتب خانے۔","پرائمری تعلیم کا فروغ؛ چھٹی جماعت سے ٹیلی کمیونیکیشن، کمپیوٹر، پٹرولیم، ٹیکسٹائل اور زراعت جیسے نئے مضامین؛ مڈل کے طلبہ میں اضافہ، 19 ہزار سیکنڈری اور 750 ہائر سیکنڈری سکولوں کا قیام اور ضلعی تعلیمی اتھارٹی۔","پیشہ ورانہ اداروں میں داخلے اور اساتذہ کی بھرتی کے لیے نیشنل ٹیسٹنگ سروس (NTS)؛ میٹرک سائنس کی طرح میٹرک ٹیکنیکل۔","اسلامیات پہلی جماعت سے بی اے تک لازمی اور آٹھویں جماعت تک ناظرہ قرآن لازمی؛ دینی مدارس میں جدید مضامین۔","دو سالہ کے ساتھ چار سالہ بی اے/بی ایس سی آنرز؛ ہر سال سو ذہین طلبہ کو سرکاری خرچ پر بیرونِ ملک اعلیٰ تعلیم کے لیے بھیجنا؛ امتحانات میں نقل اور بوٹی مافیا کا خاتمہ۔"]},{"q":[["pak12-ch9-exercise",24]],"s":["آئی ٹی (انفارمیشن ٹیکنالوجی) سے مراد کسی بھی چیز کے بارے میں بامعنی حقائق اور معلومات (ڈیٹا) کو کمپیوٹر میں محفوظ کرنا، اور انٹرنیٹ یعنی بین الاقوامی نیٹ ورک کے ذریعے معلومات اور اطلاعات کی ترسیل کے ذرائع ہیں۔","پاکستان میں فروغ کے لیے اقدامات: (1) انٹرنیٹ کے استعمال کی توسیع اور ڈیٹا کمیونیکیشن میں اضافے کی حوصلہ افزائی؛ (2) آئی ٹی اور سافٹ ویئر انڈسٹری کو برآمد کے قابل بنانا۔","(3) آئی ٹی کے ماہرین کا بڑا ذخیرہ تیار کرنا؛ (4) سکولوں اور کالجوں میں کمپیوٹر کورسز کا آغاز؛ (5) وزارتِ سائنس و ٹیکنالوجی کے تحت آئی ٹی ونگ کو ڈویژن کا درجہ دینا۔","اس کے علاوہ سرکاری اور نجی اداروں میں آئی ٹی کا نفاذ، سافٹ ویئر ٹیکنالوجی پارکس، ٹیلی کمیونیکیشن کی توسیع اور آن لائن خدمات (ای گورنمنٹ) کو فروغ دیا جا رہا ہے؛ آئی ٹی معیشت، تعلیم اور روزگار کے لیے نئے مواقع پیدا کر رہی ہے۔"]}]}},"10":{"lang":"ur","items":{"mcqs":[{"q":[["pak12-ch10-exercise-1",2]],"ob":1,"s":["1950ء کی دہائی میں پاکستان اور چین کے درمیان سرحدی تنازع پیدا ہوا جسے دونوں ملکوں نے \"پاک چین سرحدی معاہدے\" (1963ء) کے ذریعے خوش اسلوبی سے حل کر لیا۔"],"c":0},{"q":[["pak12-ch10-exercise-1",3]],"ob":1,"s":["علاقائی تعاون برائے ترقی (آر سی ڈی) کی تنظیم جولائی 1964ء میں پاکستان، ایران اور ترکی نے قائم کی۔"],"c":1},{"q":[["pak12-ch10-exercise-1",4]],"ob":1,"s":["ایرانی انقلاب کے بعد 1984ء میں آر سی ڈی کا نام بدل کر اقتصادی تعاون تنظیم (ای سی او) رکھا گیا۔"],"c":3},{"q":[["pak12-ch10-exercise-1",5]],"ob":1,"s":["پاکستان نے 1998ء میں ایٹمی دھماکے کیے۔"],"c":2},{"q":[["pak12-ch10-exercise-1",6]],"ob":1,"s":["پاکستان اور بھارت کے درمیان سندھ طاس معاہدہ 1960ء میں عالمی بینک کی ثالثی سے طے پایا۔"],"c":1},{"q":[["pak12-ch10-exercise-1",7]],"ob":1,"s":["قیامِ پاکستان کے بعد ایران وہ پہلا ملک تھا جس نے پاکستان کو تسلیم کیا۔"],"c":1}],"objective":[{"q":[["pak12-ch10-exercise-1",9]],"s":["1984ء","آر سی ڈی کا نام 1984ء میں بدل کر اقتصادی تعاون تنظیم رکھا گیا۔"],"a":"1984ء"},{"q":[["pak12-ch10-exercise-1",10]],"s":["علیحدگی پسند عناصر","1971ء میں بھارت نے مشرقی پاکستان میں علیحدگی پسند عناصر کی مدد کی جس کے نتیجے میں بنگلہ دیش وجود میں آیا۔"],"a":"علیحدگی پسند عناصر"},{"q":[["pak12-ch10-exercise-1",11]],"s":["خودکش (دہشت گرد)","ستمبر 2001ء میں امریکہ پر خودکش حملے ہوئے (11 ستمبر کے واقعات)۔"],"a":"خودکش (دہشت گرد)"},{"q":[["pak12-ch10-exercise-1",12]],"s":["ایران","ایران نے سب سے پہلے پاکستان کو تسلیم کیا۔"],"a":"ایران"},{"q":[["pak12-ch10-exercise-1",13]],"s":["غیر نیٹو (نان نیٹو) دوست","امریکہ نے پاکستان کو غیر نیٹو دوست (اتحادی) ملک کا درجہ دیا ہے۔"],"a":"غیر نیٹو (نان نیٹو) دوست"},{"q":[["pak12-ch10-exercise-1",15]],"tf":"tf","s":["غلط۔ مذہبی، تاریخی اور ثقافتی رشتوں کے باوجود قیامِ پاکستان کے بعد شروع سے افغانستان سے تعلقات دوستانہ فضا میں نہ رہ سکے۔"],"c":1},{"q":[["pak12-ch10-exercise-2",0]],"tf":"tf","s":["غلط۔ اقوامِ متحدہ میں پاکستان کی رکنیت کی مخالفت کرنے والا واحد ملک افغانستان تھا؛ ایران نے تو سب سے پہلے پاکستان کو تسلیم کیا۔"],"c":1},{"q":[["pak12-ch10-exercise-2",1]],"tf":"tf","s":["درست۔ نسلی امتیاز کی مخالفت اور حقِ خود ارادیت کی حمایت پاکستان کی خارجہ پالیسی کا بنیادی اصول ہے۔"],"c":0},{"q":[["pak12-ch10-exercise-2",2]],"tf":"tf","s":["درست۔ پاکستان نے مئی 1998ء میں ایٹمی دھماکے کیے۔"],"c":0},{"q":[["pak12-ch10-exercise-2",3]],"tf":"tf","s":["غلط۔ 1996ء میں طالبان نے کابل فتح کیا تو پاکستان وہ پہلا ملک تھا جس نے ان کی حکومت کو تسلیم کیا اور سفارتی تعلقات قائم کیے۔"],"c":1},{"q":[["pak12-ch10-exercise-2",4]],"d":"pak12-ch10-match","s":["درست جوڑ:","قیامِ پاکستان — 1947ء۔","پاک چین سرحدی تنازع — 1950ء (کی دہائی)۔","سندھ طاس معاہدہ — 1960ء۔","علاقائی تعاون برائے ترقی کی تنظیم — 1964ء۔","ایران میں اسلامی انقلاب — 1979ء۔","ڈی ایٹ تنظیم کا قیام — 1997ء۔","پاکستان کے ایٹمی دھماکے — 1998ء۔"]}],"shortQuestions":[{"q":[["pak12-ch10-exercise-2",6]],"s":["خارجہ پالیسی کسی ملک کی پالیسیوں کا وہ حصہ ہے جس کے تحت وہ دوسرے ممالک سے تعلقات قائم کرتا ہے۔","ہر ملک یہ تعلقات اپنے قومی مفادات کو مدِنظر رکھ کر قائم کرتا ہے اور حالات کے مطابق ان میں تبدیلی آ سکتی ہے۔"]},{"q":[["pak12-ch10-exercise-2",7]],"s":["1۔ اپنی آزادی اور خود مختاری کا تحفظ۔","2۔ دوسروں کی آزادی، خود مختاری اور اقتدارِ اعلیٰ کا احترام۔","3۔ دوسرے ممالک کے اندرونی معاملات میں عدم مداخلت۔","4۔ اقوامِ متحدہ کے منشور پر سختی سے عمل درآمد۔","5۔ تمام مسلمانوں کے مفادات کا تحفظ اور عالمِ اسلام کا اتحاد (نیز نسلی امتیاز کی مخالفت اور جنوبی ایشیا میں امن)۔"]},{"q":[["pak12-ch10-exercise-2",8]],"s":["انتظامی ٹرائیکا سے مراد قومی سطح کے تین اہم انتظامی عہدے ہیں: صدرِ پاکستان، وزیرِاعظم پاکستان اور فوج کا سربراہ۔","خارجہ پالیسی کی تشکیل میں یہ ٹرائیکا اہم کردار ادا کرتی ہے؛ یہ پالیسی کو منظور یا نامنظور کر سکتی اور اس میں تبدیلی لا سکتی ہے، البتہ سابقہ پالیسی اور بیرونی ممالک سے کیے گئے وعدوں کو مدِنظر رکھتی ہے۔ نئی آئینی تبدیلیوں کے مطابق قومی سلامتی کونسل اس کا متبادل بن رہی ہے۔"]},{"q":[["pak12-ch10-exercise-2",9]],"s":["علاقائی تعاون برائے ترقی (آر سی ڈی) کی تنظیم جولائی 1964ء میں پاکستان، ایران اور ترکی نے قائم کی۔","اس کا مقصد رکن ممالک کے درمیان معاشی، تجارتی، ثقافتی اور فنی شعبوں میں تعاون بڑھانا تھا۔","ایرانی انقلاب کے بعد 1984ء میں اس کا نام بدل کر اقتصادی تعاون تنظیم (ای سی او) رکھا گیا اور بعد میں افغانستان اور وسطی ایشیا کی ریاستیں بھی اس میں شامل ہوئیں۔"]},{"q":[["pak12-ch10-exercise-2",10]],"s":["وزارتِ خارجہ میں خارجہ پالیسی کے ماہرین اور اعلیٰ سطح کے افسران ہوتے ہیں۔","فرائض: خارجہ پالیسی کے بنیادی مقاصد، اصولوں اور ترجیحات کو مدِنظر رکھ کر پالیسی تیار کرنا؛ اس کے منصوبے اور پروگرام بنانا؛ پالیسی کی تشکیل میں انتظامی ٹرائیکا کی راہنمائی کرنا؛ اور دوسرے ممالک میں سفارت خانوں کے ذریعے تعلقات کو چلانا۔"]},{"q":[["pak12-ch10-exercise-2",11]],"s":["سیاسی جماعتیں اپنے منشور میں خارجہ پالیسی کو خاص جگہ دیتی ہیں؛ انتخاب جیتنے پر وہ اپنا نقطۂ نظر خارجہ پالیسی میں سامنے رکھتی ہیں۔","پریشر گروپ (دباؤ والے گروہ) بھی خارجہ پالیسی کی تشکیل کے عمل پر اثر انداز ہوتے ہیں اور حکومت کو وقت کی ضرورت کے مطابق ترجیحات بدلنے پر مجبور کرتے ہیں۔"]},{"q":[["pak12-ch10-exercise-2",12]],"s":["پاکستان نے مئی 1998ء میں بلوچستان کے علاقے چاغی میں بھارت کے ایٹمی دھماکوں کے جواب میں ایٹمی دھماکے کیے اور دنیا کی ساتویں اور عالمِ اسلام کی پہلی ایٹمی طاقت بنا۔","اس سے ملک کا دفاع ناقابلِ تسخیر ہوا اور خطے میں طاقت کا توازن قائم ہوا؛ عالمی طاقتوں نے پابندیاں لگائیں مگر سعودی عرب جیسے دوست ممالک نے مدد کی، اور 2001ء کے بعد یہ پابندیاں ختم ہو گئیں۔"]},{"q":[["pak12-ch10-exercise-2",13]],"s":["قومی سلامتی سے مراد ملک کی آزادی، خود مختاری، جغرافیائی سرحدوں، نظریاتی سرحدوں اور عوام کی جان و مال کا اندرونی و بیرونی خطرات سے تحفظ ہے۔","یہ پاکستان کی خارجہ پالیسی کا سب سے اہم مقصد ہے؛ پاکستان نیا ملک تھا، اس لیے اس کی سلامتی کا مناسب انتظام ضروری تھا اور غیر ملکی تعلقات میں ہمیشہ قومی سلامتی کو اہمیت دی گئی۔","پاکستان دوسرے ممالک کی علاقائی سالمیت کا احترام کرتا ہے اور توقع رکھتا ہے کہ دوسرے بھی اس کی قومی سلامتی کا احترام کریں۔ آج قومی سلامتی میں معاشی استحکام، توانائی، دہشت گردی کا خاتمہ اور سائبر تحفظ بھی شامل ہیں۔"]}],"longQuestions":[{"q":[["pak12-ch10-exercise-2",14]],"s":["خارجہ پالیسی کسی ملک کی وہ پالیسی ہے جس کے تحت وہ قومی مفادات کے مطابق دوسرے ممالک سے تعلقات قائم کرتا ہے۔","تشکیل کے ذرائع: (1) انتظامی ٹرائیکا — صدر، وزیرِاعظم اور فوج کا سربراہ پالیسی منظور، نامنظور یا تبدیل کر سکتے ہیں۔ (2) وزارتِ خارجہ — ماہرین اور اعلیٰ افسران پالیسی، منصوبے اور پروگرام تیار کرتے ہیں۔","(3) خفیہ ایجنسیاں — دوسرے ممالک کی خارجہ پالیسیوں کے مقاصد کے بارے میں مکمل معلومات فراہم کرتی ہیں۔ (4) سیاسی جماعتیں اور پریشر گروپ — منشور اور دباؤ کے ذریعے اثر انداز ہوتے ہیں۔","(5) پارلیمنٹ — وزارتِ خارجہ پالیسی کو قومی اسمبلی اور سینیٹ میں پیش کرتی ہے جہاں بحث کے بعد اس کی منظوری دی جاتی ہے۔ نئی آئینی تبدیلیوں میں قومی سلامتی کونسل کا کردار بھی بڑھا ہے۔"]},{"q":[["pak12-ch10-exercise-2",15]],"s":["پاکستان کو برطانوی ہند سے کوئی خارجہ پالیسی ورثے میں نہیں ملی؛ نظریۂ پاکستان اور تحریکِ پاکستان کے مقاصد کو مدِنظر رکھ کر خارجہ پالیسی بنائی گئی۔","(1) قومی سلامتی: سب سے اہم مقصد ملک کا تحفظ اور علاقائی سالمیت ہے۔","(2) معاشی ترقی: پاکستان ترقی پذیر ملک ہے، اس لیے ان تمام ممالک سے اچھے تعلقات چاہتا ہے جن سے تجارت، معاشی امداد اور ترقی حاصل ہو سکے۔","(3) نظریاتی تحفظ: پاکستان نظریاتی ریاست ہے؛ اپنی نظریاتی سرحدوں کے تحفظ کے لیے اسلامی ممالک سے بہتر تعلقات قائم کیے؛ او آئی سی اور ای سی او کے قیام میں اہم کردار ادا کیا۔","(4) دیگر مقاصد: عالمی امن کا فروغ، اقوامِ متحدہ کے منشور کی پاسداری، حقِ خود ارادیت (کشمیر) کی حمایت، نسلی امتیاز کی مخالفت، منصفانہ عالمی معاشی نظام اور جنوبی ایشیا میں امن و تعاون۔"]},{"q":[["pak12-ch10-exercise-2",16]],"s":["آغاز: پاکستان معاشی طور پر کمزور تھا، اس لیے اس نے ترقی یافتہ ممالک خصوصاً امریکہ سے قریبی تعلقات قائم کرنے کی کوشش کی۔","1950ء کی دہائی: پاکستان امریکی بلاک میں شامل ہوا اور سیٹو (SEATO) اور سینٹو (CENTO) کا رکن بنا؛ امریکہ سے بڑی معاشی اور فوجی امداد ملی۔","1960ء کی دہائی: 1962ء میں بھارت کو امریکی اسلحہ اور 1965ء کی جنگ میں امریکہ کے رویے سے مایوسی کے بعد صدر ایوب خان نے پالیسی پر نظرثانی کی اور چین و روس سے تعلقات بڑھائے؛ امریکی اڈے بند کرائے گئے۔","1979ء کے بعد: ایرانی انقلاب اور افغانستان میں سوویت مداخلت کے باعث امریکہ نے دوبارہ پاکستان پر توجہ دی؛ افغان جہاد کے دوران قریبی تعاون رہا۔ سوویت انخلا کے بعد 1990ء میں پریسلر ترمیم کے تحت پابندیاں لگیں اور 1998ء کے ایٹمی دھماکوں پر مزید پابندیاں۔","اکیسویں صدی: 11 ستمبر 2001ء کے بعد پاکستان دہشت گردی کے خلاف جنگ میں امریکہ کا اتحادی بنا؛ پابندیاں ختم ہوئیں اور امریکہ نے پاکستان کو غیر نیٹو دوست ملک کا درجہ دیا۔ تاہم یہ تعلقات اتار چڑھاؤ کا شکار رہے ہیں۔"]},{"q":[["pak12-ch10-exercise-2",17]],"s":["(الف) افغانستان: مذہبی، تاریخی اور ثقافتی رشتوں کے باوجود تعلقات شروع سے خوشگوار نہ رہے؛ افغانستان واحد ملک تھا جس نے اقوامِ متحدہ میں پاکستان کی رکنیت کی مخالفت کی؛ 1955ء اور 1963ء میں سفارتی تعلقات منقطع ہوئے۔ اس کے باوجود پاکستان نے افغانستان کو تجارتی راہداری (ٹرانزٹ) کی سہولت دی۔ 1978ء کے کمیونسٹ انقلاب اور 1979ء میں سوویت مداخلت کے بعد پاکستان نے لاکھوں افغان مہاجرین کو پناہ دی اور مجاہدین کی حمایت کی؛ 1992ء میں مجاہدین حکومت اور 1996ء میں طالبان حکومت کو تسلیم کیا؛ 2001ء کے بعد کرزئی حکومت کو بھی تسلیم کیا۔","(ب) ایران: ایران وہ پہلا ملک ہے جس نے پاکستان کو تسلیم کیا؛ صدیوں پرانے مذہبی و ثقافتی رشتے ہیں۔ دونوں سینٹو، آر سی ڈی (1964ء) اور ای سی او کے رکن رہے؛ ایران نے پاک افغان سفارتی تعلقات کی بحالی میں مدد کی اور 1965ء و 1971ء کی جنگوں میں پاکستان کا ساتھ دیا؛ پاکستان نے ایران عراق جنگ اور ایران مصر تعلقات میں مصالحت کی کوشش کی۔","(ج) سعودی عرب: تعلقات بہت پرانے ہیں؛ تحریکِ پاکستان میں سعودی حکومت نے مسلم لیگ کی حمایت کی اور ابتدا ہی میں پاکستان کو تسلیم کیا۔ ہر مشکل وقت میں سعودی عرب نے سفارتی، اخلاقی اور معاشی مدد دی؛ 1998ء کے ایٹمی دھماکوں کے بعد پابندیوں کے دوران تیل کی سہولت دی اور 8 اکتوبر 2005ء کے زلزلے میں بھرپور امداد کی۔ دفاعی شعبے میں بھی قریبی تعاون جاری ہے اور لاکھوں پاکستانی وہاں روزگار سے وابستہ ہیں۔"]},{"q":[["pak12-ch10-exercise-2",18]],"s":["مسئلۂ کشمیر پاک بھارت تنازع کی بنیادی وجہ ہے جس پر کئی جنگیں ہو چکی ہیں؛ بھارت اقوامِ متحدہ کی قراردادوں کے مطابق کشمیریوں کو حقِ خود ارادیت دینے سے انکاری ہے۔","11 ستمبر 2001ء کے بعد عالمی سیاست میں آزادی کی مسلح تحریکوں کو دہشت گردی کے زمرے میں رکھا جانے لگا؛ بھارت نے اس صورتحال سے فائدہ اٹھا کر کشمیری جدوجہد کو دہشت گردی قرار دیا اور پاکستان پر الزامات لگائے۔","پاکستانی راہنماؤں نے دہشت گردی اور آزادی کی تحریکوں کا فرق واضح کرنے کی بھرپور کوشش کی مگر عالمی برادری اپنی سوچ بدلنے پر آمادہ نہ ہوئی؛ پاکستان کے دہشت گردی کے خلاف جنگ میں امریکہ کا اتحادی ہونے نے بھی اس کی پالیسی کو محدود کیا۔","اقوامِ متحدہ اور عالمی برادری بھی کشمیر جیسے مسئلے پر ثالثی سے گریز کرتی ہیں، جبکہ دونوں ملکوں کا ایٹمی طاقت ہونا مسئلے کو مزید حساس بنا دیتا ہے۔","ان حالات میں پاکستان کو اپنی کشمیر پالیسی پر نظرثانی کرنا پڑی: اصولی مؤقف (کشمیری عوام کی مرضی کے مطابق فیصلہ) برقرار رکھتے ہوئے اب کوشش یہ ہے کہ مسئلہ مذاکرات کے ذریعے حل ہو اور تمام کشمیری فریقوں کو بات چیت میں شامل کیا جائے۔"]}]}},"11":{"lang":"ur","items":{"mcqs":[{"q":[["pak12-ch11-exercise-1",2]],"ob":1,"s":["1947ء میں پاکستان کی آبادی تین کروڑ تیس لاکھ (33 ملین) تھی جو 2004–05ء میں 151.1 ملین ہو گئی۔"],"c":2},{"q":[["pak12-ch11-exercise-1",3]],"ob":1,"s":["1950ء میں آبادی کے لحاظ سے پاکستان دنیا میں چودھویں نمبر پر تھا، جبکہ 2004ء میں چھٹے نمبر پر آ گیا۔"],"c":1},{"q":[["pak12-ch11-exercise-1",4]],"ob":1,"s":["2004ء کے اعداد و شمار کے مطابق ملک میں 36 لاکھ افراد بے روزگار ہیں۔"],"c":2},{"q":[["pak12-ch11-exercise-1",5]],"ob":1,"s":["2014ء کے اعداد و شمار کے مطابق پاکستان میں 1073 افراد کے لیے ایک ڈاکٹر دستیاب ہے، جو بین الاقوامی معیار سے بہت کم ہے۔"],"c":1},{"q":[["pak12-ch11-exercise-1",6]],"ob":1,"s":["1998ء کی مردم شماری کے مطابق شرحِ خواندگی 45 فیصد تھی اور 2004ء کے اندازوں کے مطابق 54 فیصد ہے۔"],"c":3}],"objective":[{"q":[["pak12-ch11-exercise-1",8]],"s":["796096","پاکستان کا کل رقبہ 796096 مربع کلومیٹر ہے جو دنیا کے کل رقبے کا 0.67 فیصد ہے۔"],"a":"796096"},{"q":[["pak12-ch11-exercise-1",9]],"s":["2.9","پاکستان کی آبادی میں ہر سال 2.9 ملین افراد کا اضافہ ہو رہا ہے، یعنی ہر منٹ میں 8 بچوں کا۔"],"a":"2.9"},{"q":[["pak12-ch11-exercise-1",10]],"s":["چھ (چھٹے)","2004ء میں آبادی کے لحاظ سے پاکستان دنیا میں چھٹے نمبر پر آ گیا۔"],"a":"چھ (چھٹے)"},{"q":[["pak12-ch11-exercise-1",11]],"s":["15","ہمارے ملک میں پرائمری سکول جانے کی عمر کے 15 فیصد بچے سکول میں داخل ہی نہیں ہوتے۔"],"a":"15"},{"q":[["pak12-ch11-exercise-1",12]],"s":["54","2004ء کے اندازوں کے مطابق ہماری شرحِ خواندگی 54 فیصد ہے۔"],"a":"54"}],"shortQuestions":[{"q":[["pak12-ch11-exercise-2",1]],"s":["ملک میں بے روزگاری کی صورتحال تشویشناک ہے؛ 2004ء کے اعداد و شمار کے مطابق 36 لاکھ افراد بے روزگار ہیں۔","حکومت چھوٹی سکیموں اور چھوٹے و درمیانے کاروبار کے لیے آسان شرائط پر قرضوں جیسے اقدامات کر رہی ہے، مگر دیہات میں روزگار کے محدود مواقع کی وجہ سے دیہی آبادی شہروں کی طرف منتقل ہو رہی ہے، جس سے شہروں پر آبادی کا دباؤ اور آبادی و وسائل کا عدم توازن بڑھ رہا ہے۔"]},{"q":[["pak12-ch11-exercise-2",2]],"s":["معاشی ترقی کی رفتار اور آبادی میں اضافے کی رفتار کا گہرا تعلق ہے؛ آبادی تیزی سے بڑھے تو خوراک، لباس، رہائش، تعلیم، صحت اور بجلی، پانی، گیس جیسی سہولیات کی فوری فراہمی ممکن نہیں رہتی۔","طلب و رسد کا فرق بڑھتا ہے، دستیاب وسائل دباؤ کا شکار ہوتے ہیں، معیارِ زندگی گرتا ہے، بے روزگاری بڑھتی ہے اور بڑھتی آبادی کو موجودہ معاشی معیار پر رکھنے کے لیے کئی گنا زیادہ سرمایہ کاری درکار ہوتی ہے۔"]},{"q":[["pak12-ch11-exercise-2",3]],"s":["تیزی سے بڑھتی آبادی کی وجہ سے زیرِ کاشت رقبہ کم ہو رہا ہے؛ وراثت میں نسل در نسل تقسیم سے زمین چھوٹے چھوٹے ٹکڑوں میں بٹ رہی ہے اور فی کس زرعی رقبہ گھٹ رہا ہے۔","آبپاشی کے لیے پانی کے ذرائع کم ہو رہے ہیں؛ سیم اور تھور سے زمین خراب ہو رہی ہے؛ خوردنی تیل اور دالوں کی پیداوار ضرورت سے کم ہے؛ کھادوں، زرعی ادویات اور پانی کے سائنسی استعمال کی کمی ہے۔"]},{"q":[["pak12-ch11-exercise-2",4]],"s":["ماحولیاتی آلودگی پیدا کرنے والے عوامل: (1) آبادی میں تیز اضافہ — وسائل پر شدید دباؤ؛ (2) شہروں کا پھیلاؤ اور کچی آبادیاں جن میں سڑکوں، نکاسی اور صفائی کی سہولیات نہیں۔","(3) صنعتیں — زہریلا فضلہ صاف کیے بغیر پانی اور زمین میں پھینکنا؛ (4) ذرائع آمد و رفت — 70 فیصد گاڑیاں اپنی عمر پوری کر چکی ہیں اور سیاہ دھواں اور سیسہ خارج کرتی ہیں؛ (5) کوڑا کرکٹ — پلاسٹک اور ڈبہ بند اشیا کا فضلہ۔","(6) گندا پانی — جس سے سبزیاں اور فصلیں سیراب کی جاتی ہیں؛ (7) کیمیائی کھادوں اور کیڑے مار ادویات کا بے جا استعمال؛ (8) جنگلات کی کٹائی — جنگلات صرف 4.8 فیصد رقبے پر ہیں جبکہ عالمی معیار 25 فیصد ہے۔"]}]}}});
